                values: new object[,]
                {
                    { 407, "عبد الله منجود", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يُبرِز كتيبُ الدكتور عبد الله منجود أسرارَ الصومِ ومقاصدَه مُستلهِمًا نصوصَ السلفِ، ومُضيفًا إليها بصائرَ تُواكِبُ روحَ العصر.\nإنه مدخل لمن أراد أن يتذوّق تدبر أسرار ومقاصد الصوم بمعناه الكامل: عبادةً، وتسليما وتقوي.\nيمضي المؤلف بالقارئ في رحلة تأملية، تمتد من آيات القرآن وأقوال الرسول صلي الله عليه وسلم والصحابة والتابعين ، إلى تساؤلات الإنسان المعاصر وهمومه الروحية. فلا يتناول المؤلف جفاف الفقه ،أو غموض التصوف المجرد، بل توازن بين المعرفة والحكمة ، لإكتشاف أسراره الدفينة بما يفتح الله علي كل متدبر من عمق المعنى، وتزكية النفس.", "/images/products/9786339968044.webp", "9786339968044", "تدبر مقاصد الصوم وأسراره", null, 100m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 408, "عبد الله منجود", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يُقدِّم كتاب (دليل المؤمنين لتدبّر كتاب رب العالمين ) للدكتور عبد الله محمد منجود رؤيةً عمليّةً\nفي تدبّر القرآن، مستلهمًا روح الصحابة والتابعين - رضوان الله عليهم - الذين تلقّوا كلام الله من فم رسول الله ﷺ، فتفاعلوا معه واهتدوا بهداه وتقبلوه بقلوبٍ واعيةٍ، وعقولٍ متفتحةٍ، وتطبيق عملي ،\nحتى صار القرآن ملازمهم في القول والعمل.\n\nوالكتاب نتيجة (لأكثر من عشر سنوات من تدريس التدبر كمنهج عملي وقواعد في التعامل مع القرآن\nمبني على أسس علمية مقررة عند أهل التفسير في فهم كلام الله عز وجل وتفهميه للناس وتطبيقه ،\nقد أثبتت التجربةُ فاعليته في تحويل التدبّر إلى عبادة (تثمر) تحوُّلًا جذريًا في حياة الملتزم به.\n\nإنه دعوة صادقة للعودة إلى القرآن كما نزل: هاديًا، مصلحًا، ومغيّرًا، يعتمد على الفهم السليم والتطبيق لهدي القرآن الكريم فى تزكية النفوس.", "/images/products/9786339969430.webp", "9786339969430", "دليل المؤمنين لتدبر كتاب رب العالمين", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 409, "هاني الغيتاوي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إعدام الياسمين — هاني الغيتاوي. من إصدارات دار واحة الأدب للنشر والتوزيع.", "/images/products/9786339969478.webp", "9786339969478", "إعدام الياسمين", null, 200m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 410, "عبد الله ناصر", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "خذت آمنة نفسًا عميقًا وبدأت لحظة الولادة، وقبل أن يخرج منها الرضيع انبثق منها نور أبيض اخترق جدران البيت فامتد في الأفق حتى طُويت الأرض فأضاء قصور الشام البعيدة، ولمحتُ آمنة تنظر بدهشة إلى هذا الضوء وكأن الحُجبَ قد كُشفت عن بصرها فرأت مشارق الأرض ومغاربها.", "/images/products/9786339968075.webp", "9786339968075", "جلست بين يدى رسول الله", null, 200m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 411, "فاطمة شيبانى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "نظرا لكثرة الذنوب والمعاصي والملهيات والمشتتات والبعد عن الله وخراب الذم واستحلال الحرام وتحريم الحلال والعبث في ثوابت الدين، والتشكيك فيما هو معلوم من الدين بالضرورة، والتطاول على سنة نبينا صل الله عليه وسلم، وانتشار البدع\nفذلك يدفعنا لإيجاد روتين لترميم النفس كما يوجد روتين لترميم الجسد", "/images/products/9786339968051.webp", "9786339968051", "روتين النفس المطمئنة", null, 100m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 412, "عبدالله ناصر", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "طبيب شاب يجد نفسه فجأة في قلب مملكة سحرية مهددة بالدمار. بينما هناك مخطوطة غامضة يحمل مفتاح إنقاذ إيلدامورا أو سقوطها. ووسط صراع ملحمي بين قوى الخير والشر، ليكتشف كريم أن مصيره مرتبط بهذا العالم أكثر مما يتخيل. هل سيتمكن من فك رموز الكتاب وإنقاذ المملكة قبل فوات الأوان؟", "/images/products/9786339968068.webp", "9786339968068", "مملكة إيلداموار", null, 200m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 413, "عبدالله ناصر", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لا تخرج عند اكتمال القمر… لا تذكر اسم المندور… واحذر أن تدخل هذه القرية ليلًا، وإن وطئتها نهارًا فاخرج قبل المغيب.\nففيها الجن يتناحرون من أجل الروهانا، والناس يموتون، واللعنة لا ترتوي، ولا تهدأ، ولا تنتظر حتى تفهمك؛ يكفي أن يمر عليك قمرٌ واحد، حتى يُكتب اسمك في سِلْسَال الدماء.", "/images/products/9786339968082.webp", "9786339968082", "الروهانا وليدة الفجر السابع", null, 200m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 414, "محمد عمرو سامى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "قراءة جديدة للقرآن الكريم كمنظومة معرفية كونية متكاملة، لا ككتاب هداية روحيّة فقط. ينطلق الكتاب من سؤال جوهري: هل يوجد جسر حقيقي بين الوحي الإلهي والعلم التجريبي الحديث؟\nنستكشف الاجابة عبر أربعة محاور كبرى: الإعجاز اللغوي والبياني، الإعجاز العلمي، الإعجاز الرقمي والعددي، ثم الإطار النظري المتقدم المتمثل في أكثر من 160 نظرية علمية مستنبطة من الأنماط الرياضية القرآنية، تمتد من فيزياء الطاقة والمعلومات إلى علوم النانو والفيزياء الكمومية وعلوم الوعي. يربط الكتاب بين الدقة المعجزة في اختيار الألفاظ القرآنية وبين حقائق كونية مكتشفة حديثاً، ويبرهن بالأرقام والمعادلات على وجود نظام عددي محكم في بنية السور والآيات والكلمات، يكشف عن تناغم عجيب بين اللغة والعدد والكون. لا يكتفي هذا العمل بعرض وجوه الإعجاز المعروفة، بل يتقدم خطوة أبعد ليقترح إطاراً نظرياً جديداً لفهم العلاقة بين الطاقة والمعلومات والوعي والزمن، من خلال نظريات مثل: التردد الكوني المتناغم، المجال الزمني غير الخطي، التجانس الكمي المعلوماتي، التنظيم الذاتي النانوي المتناغم، والوعي الكمومي متعدد المستويات. هذه النظريات لا تُطرح كشعارات عامة، بل تُبنى على أنماط رقمية دقيقة في النص القرآني، مع إثباتات رياضية وصيغ ومعادلات وتطبيقات مقترحة في الطاقة المتجددة، والطب، والاتصالات، والبيئة، والحوسبة المتقدمة.\n\nيتكوّن هذا الكتاب من 4 أجزاء: التفرد الإعجازى للقرآن الكريم الجزء الأول، التفرد الإعجازى للقرآن الكريم الجزء الثانى، التفرد الاعجازى للقرآن الكريم الجزء الثالث، التفرد الاعجازى للقرآن الكريم الجزء الرابع.", "/images/products/9786339969409.webp", "9786339969409", "التفرد الإعجازى للقرآن الكريم الجزء الأول", null, 300m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 415, "هانى الغيتاوى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ولكل كتاب رسالة، ورسالتي من هذا الكتاب هي التمرد على القبح وصنع الجمال بعذب الكلمة وسحر معناها، وأنا لا أدعي عذب الكلمة وسحرها وإن كنت أحسبها كذلك، لكن الحكم والتقييم لك عزيزي القارئ، واعلم أن هذه العبارات نتاج قدح فكر، وعناء تجربة، ومواقف لامست الوجدان وأخرى هيجت الانفعالات الحزينة، وأراني أعتقد أنَّ كلَّ ما كُتب في هذا الكتاب، هو دعوة للحب وللجمال، وكما يقول \"رالف أميرسون\" في كتابه \"الجمال مفعّل الحياة\": \"الحب يُعلي من طاقة الموهبة وبه نتغلب على العثرات\"، والحياة كما يقول الدكتور عمار علي حسن: \"مكابدات لا تنتهي وكدح لا يتمهل ومعاناة لا تكف\"", "/images/products/9786339969423.webp", "9786339969423", "همس الفكر و الخطايا", null, 250m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 416, "مريم محمد الدالى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أَنْفُورْجِيَا\n​في مكان ما بين الألم والأمل، تبدأ قصة لا تُكتب فقط لتُروى،\nبل لتُشعر وتُعاش.\nهل هي ضحية؟ أم بطلة تخوض معركة خفية؟\nوراء كل جرح، وكل ابتسامة،\nتكمن حقيقة غائبة عن الأنظار؛\nصوت لم يسمعه أحد، ودمعة لم يرها أحد.\nهل يمكن للروح أن تلتئم بعد كل ما حدث؟\nأم أن هناك جرحاً لا يشفى أبداً؟\nقد تكون الإجابة أعمق مما نتصور،\nوأقرب مما نريد أن نراه،\nمختبئة في الزوايا التي نتهرب منها.", "/images/products/9786339969447.webp", "9786339969447", "أنفورجيا", null, 100m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 417, "شيرى الجرف", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لقدر أهازيج ربما تكون سالبة للأنفاس عندما يحمل بين ألحانه العشق والشغف فتجده لحنا يداهم قلبك مربتًا على روحك..لكن من منا يتحكم في قدره أو له السلطة عليه..فالقدر مكتوب لكن لا يمكنك قراءته..\nفي لحظة تتغير الأقدار لتجدها أهازيج صاخبة ومؤلمة لقلبك الذي أضحى يبكي الفراق والفقد صارخًا بآلم عندما يخسر من كان له الحياة..\nلذا انتبه يا صديقي فبداخل سطور قصتنا ستجد للقدر ألاعيب تعلمك أن للخطأ عواقب ربما لن تتحملها، لذا كن مخلصًا قبل أن تكون عاشقًا حتى لا تدفع الثمن من روحك وقلبك الذي سيصارع إلى مالا نهاية.", "/images/products/9786339969454.webp", "9786339969454", "أهازيج القدر", null, 250m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 418, "مروة طلعت", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ليس التاريخ ما كُتب فقط، بل ما ترك أثرًا وبقي. التاريخ ليس مجرد أسماء تمرّ في الصفحات، بل حكايات ناس عاشوا زمنهم بصدق، وتركوا أثرًا ظلّ ثابتًا رغم تغيّر الوجوه وتعاقب السنين. هذا الكتاب رحلة هادئة للبحث عمّا تبقّى خلف الجدار؛ عن أصوات خفتت، لكن حضورها لم يغب، وعن وجوه صنعت لحظتها ثم انسحبت في صمت، تاركة بصمتها شاهدة على أنها كانت هنا.", "/images/products/9786339969461.webp", "9786339969461", "أثر على جدار الزمن", null, 200m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 419, "شيرى الجرف", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أركض بين أروقة الماضي أُلملم بقايا الذكريات.\nأطرق أبوابًا عتيقة، موصدة بأقفالًا قد صدئت بدموع الفراق.\nأين أنا؟\nوكيف تناقضت روحي هكذا بين الماضي والحاضر.\nلقد نفيت من تعقلي وجعلت الفوضى موطني.\nأحلامي أضحت جاثوم خانق.\nروحي تائهة بين غياهب الذكريات.\nقُل لي أيا عشقًا ظلمني لأي عالم كنت أنتمي.\nياعشقًا أحياني وقتلني.\nيا آلم ينبض بين أضلعي.\nيا طيف حبيب غائب ترفق بي، فالجنون يكاد يزورني.", "/images/products/9786339969485.webp", "9786339969485", "بين أروقة الماضى", null, 250m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 420, "شيرى الجرف", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هل أهداهم القدر حياة جديدة،\nأم لعنهم بآخرى غيرت حياتهم ودمرت أحلامهم البريئة..بعدما خسروا براءة الطفولة وحصنهم الآمن، تركهم مابين طعنة غدر، وأيدي حاقدة غرست تجتث أوردتهم البريئة حتى نُزفت أخر قطرات النقاء وحل محلها ضراوة الانتقام، وجمود قلب تَعلم ألا يعرف للرفق طريق..وبين آتون الحب والحقد اتحد الأخوه، ليس لتحويل الجبال إلى ذهب، انما لتفتيتها وتحويلها لإعصار ساحق لن يردعه رادع.", "/images/products/9786339970306.webp", "9786339970306", "آتون الحب و الحقد", null, 250m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 421, "حسن الشريف", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إبان الرحيل بالداخل\nكانت تسافر إلى المجهول\nفي مناطق اللغة\nأبجدية العثور على النظير\nوالظهير المقابل\nكالأفكار التي تتناثر محلقة\nبين أروقة الكتب\nفي عرف الفراشة\nفراسة المرء خفة\nفي لحظات الحب العاصفة\nوالترقب الصارخ كضوضاء\nهامسة بالهدوء\nقبع الوله مملوء بالضجيج\nسائرة بين الدروب\nتلملم المدى كمظلة\nحمراء\nتشع من ثغرها البهجة\nمنبعثة من الأعماق\nمنيرة في محيطها\nانصهري أيتها الشمس\nفي يدها أزهار سائلة\nذهبية اللون تفوح بالأريج\nيتراقص الظل الساطع\n​الشاعر والكاتب حسن الشريف", "/images/products/9786339970313.webp", "9786339970313", "أوراق المطر", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 422, "أمل القادرى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "عد أن خمدت نيران زِيين وانطفأ نسله، لم يكن الانتصار إلا بداية لمعركة أخرى… داخلية.\n\nسيلين، من تحدّت الظلام لأجل من تحب، تواجه قرارًا قلب موازينها.\nداميان، من ظنّ أن قلبه مات قبل قرنين، يعثر على توأم روحه خلف جدران الأسر.\nكايدين، الملك الذي نذر نفسه لحماية شعبه، يجد أن التحدي الحقيقي يبدأ حين يسكن السكون، ويعلو صوت الروح الممزقة.\n\nفي عالمٍ ينهض من رماده، يبدأ الأبطال رحلة البحث عن ذواتهم المبعثرة، وعن خلاص لا يأتي بالسيوف… بل بالمواجهة الصامتة لما تركته الحرب خلفها.\n\n“أحياناً، لا يكون أصعب ما في المعركة هو القتال… بل البقاء بعد انتهائها.”", "/images/products/9786339970320.webp", "9786339970320", "دماء الشمس", null, 300m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 423, "أمل القادرى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "عد أن خمدت نيران زِيين وانطفأ نسله، لم يكن الانتصار إلا بداية لمعركة أخرى… داخلية.\n\nسيلين، من تحدّت الظلام لأجل من تحب، تواجه قرارًا قلب موازينها.\nداميان، من ظنّ أن قلبه مات قبل قرنين، يعثر على توأم روحه خلف جدران الأسر.\nكايدين، الملك الذي نذر نفسه لحماية شعبه، يجد أن التحدي الحقيقي يبدأ حين يسكن السكون، ويعلو صوت الروح الممزقة.\n\nفي عالمٍ ينهض من رماده، يبدأ الأبطال رحلة البحث عن ذواتهم المبعثرة، وعن خلاص لا يأتي بالسيوف… بل بالمواجهة الصامتة لما تركته الحرب خلفها.\n\n“أحياناً، لا يكون أصعب ما في المعركة هو القتال… بل البقاء بعد انتهائها.”", "/images/products/9786339970337.webp", "9786339970337", "أنين الروح", null, 300m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 424, "أمل القادرى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ثلاث وعشرون سنة مرّت…\nوها هو القلب الملعون ينبض من جديد.\n\nقلبٌ أُغلق عليه بين الأضلاع منذ آلاف السنين، حين سُجن “لوسيفر” بتعويذة سحرية خنقته في سبات أبدي.\nلكن هناك من لم ينسَ…\nمصاص دماء مرتد، لا يزال يسعى لإحياء سيده، مهما كلّف الأمر.\n\nعودة لوسيفر ليست مجرد نبوءة… إنها كارثة تتسلّل من بين الظلال، معلنة بدء النهاية، وجحيمًا يوشك أن يبتلع الأرض.\n\nوفي مواجهة هذا المصير، يقف التوأم “كايل” و”آرُن”، أبناء كايدين، ليس فقط لحماية العالم، بل لحماية من اختارتهم قلوبهم… في زمنٍ لم يعد فيه الحب كافيًا، ولا الدم كفيلًا بالنجاة.\n\nفهل يكفي النور المتوارث في عروقهم لإخماد الظلام الذي نهض من رماده؟\nأم أنّ قلب التنين… سينبض بالموت؟", "/images/products/9786339970344.webp", "9786339970344", "قلب التنين", null, 300m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 425, "أمل القادرى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "استيقظت من غياهب العدم، في حفرة على جزيرة تنبض بالأسرار ، بلا اسم… بلا ذاكرة… وكأنّها وُلدت من جديد في أرض المجهول.\nفي مستعمرة خفية، تتوارى عن أنظار الملك كايدين، وجدت نفسها أسيرةً لقوانين صارمة، وأصواتٍ تهمس من الظلال أن ماضيها أخطر مما تتخيّل.\n\nوهناك… التقت به.\nعبدٌ هارب، يحمل جسده وشم العذاب، وروحه موصولة بجحيم لم ينطفئ. فارس بلا مملكة، وطيفٌ من أسطورة منسيّة، لا يثق بأحد… ولا ينتظر النجاة.\n\nبينهما تنبعث شرارة من نور ، كأنها مكتوبة منذ قرون.\nفهل يكون لقاؤهما خلاصاً… أم بوابة إلى لعنة لا عودة منها؟", "/images/products/9786339970351.webp", "9786339970351", "أطياف الجحيم", null, 300m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 426, "محمد جاد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هل سبق أن نظرت في المرآة طويلًا… دون أن تعدل شعرك؟ دون أن تضبط هندامك؟\nهل جرّبت أن تحدّق في وجهك دون حُكم، دون نية مسبقة، دون أن تهرب من الملامح التي تفضحك أكثر مما تظهرك؟\nأنا لا أسألك عن ملامحك، بل عن وجهك الحقيقي.\nذاك الوجه الذي يظهر فقط عندما تنفرد بنفسك… وتكفّ عن التمثيل.\nاسأل نفسك الآن:\nمن أنا حين لا يراني أحد؟\nمن هذا الذي يقف خلف نظراتي، ويتكلم داخل رأسي، ويخاف أن يُكشَف؟", "/images/products/9786339971051.webp", "9786339971051", "غرفة خمس نجوم", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 427, "محمد رضا إبراهيم", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "فلسطين ليست خارطة على ورق، بل جرحٌ نابض، وصرخةُ شعبٍ لا تندمل.\nلن تُمحى من الذاكرة، ولا تُدفن في التاريخ.\nهذه الأرض، كل ذرة فيها تصرخ: فلسطين للفلسطينيين، والاحتلال إلى زوال.\nهذا ليس قدَرًا.. بل ظلم عابر، سيزول بإذن الله وقوة الحق", "/images/products/9786339970368.webp", "9786339970368", "جرائم المحتلين في أرض فلسطين من النكبة حتى اليوم", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 428, "مديحة ممدوح عارف", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدور احداث رواية مستعمرة ما بعد الموت عن مدينة تشتعل بها حرب خفية بين الطموح والخداع، ويغدو الدم أثمن من الذهب.تتحول الحياة إلى وباء، والماء إلى سرّ لا يُشرب، فيما ينهض من الرماد عالم لا يرحم.\nيهرب الناجون إلى حصنٍ بُني قبل النهاية بوقتٍ طويل، لكن جدرانه تعرف أكثر مما تُخفي.\nيعود الماضي ليحاكم الحاضر، وتتشابك الأزمنة كأنها تتنفس من جرحٍ واحد.\nوعندما يظهر \"الظل\"، يدرك الجميع أن الموت لم يكن سوى بداية المستعمرة.", "/images/products/9786339970375.webp", "9786339970375", "مستعمرة ما بعد الموت", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 429, "أحمد أيوب", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"أحيانًا، لا يولد الأبطال من رحم العدالة... بل من شرارات العداء!\"\n\nفي عالم يطفو على حافة الانهيار، وعروش تتصدّع تحت وطأة الجشع والهيمنة، تجتمع نقيضتان: أحمد أيوب، الضابط المنضبط في خدمة النظام، ومورجانا، قائدة قراصنة جامحة ترفض الانصياع لأي قانون. لم يكن من المفترض أن يتحالفا… لكن الخطر الذي يُهدد المجرة بأسرها لا يفرق بين عدو وحليف.\n\n\"عرش النجوم\" ليست مجرد ملحمة فضائية، بل صراع داخلي عن الهوية، الولاء، والحب المولود من رماد المعارك. على مدار رحلتهم، تنقلب القواعد، وتتغير التحالفات، ويواجه كل منهما ماضيه، ليكتشف أن مفتاح النصر ليس في السلاح الأقوى… بل في قوة الروح والتضحية.\n\nحين يُفعّل \"العرش\"، لا يستجيب إلا لنقاء القلوب. وفي لحظة واحدة، تتحول المعركة من أجل السيطرة... إلى معركة من أجل معنى الحياة نفسه.", "/images/products/9786339970382.webp", "9786339970382", "عرش النجوم", null, 200m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 430, "طارق عزب", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كان اللهُ ولم يكن معهُ شيءٌ فهو اللهُ إن خَلَقَ شيئاً وإن لم يخلق أيَّ شيءٍ، هو العظيمُ في ذاتهِ دائماً وأبداً دونَ بدايةٍ ولا نهاية.\nثم خلقَ المكانَ وهو السمواتُ والأرض، وهو المُنَزّهُ عن الزمانِ وعن المكانِ وهو خالِقُهُما, وهو غيرُ موجودٍ, اِنّهُ خالقُ الاكوان التي هي الوجودُ الحادِثُ لِفِعلِهِ وهو مُنزَّهٌ عنهُ فهو ليس اَعلاه, هو فوقَ كلِّ شيءٍ وليس تحتَهُ شيء, وهو في كلّ شيءٍ وليس كشيءٍ في شيء, هو الواحدُ بلا عدد وقائم بلا عمَد لا يُسالُ عنه بمتىَ كان, فهو خالقُ الزمان ولا يُساَلُ عنه بِاَينَ فهو خالقُ المكان.\nاِنّ اَفعالَ اللهِ حادثةٌ وهو اَزَليٌّ كُلّيُّ العِلمِ والقُدرة, هو الازَليُّ في وجودهِ بلا بدايةٍ والسّرمديُّ بلا نهاية, صَمَدٌ على ما هو عليهِ, فهو خارجُ مَنظومةِ الحادِثِ وما فيها مِن مقاييسٍ ومواصفات فهو خارجٌ عن الزمكان فلا ينطبقُ عليهِ ما ينطبقُ على منظومةِ الكونِ والمخلوقات. لا ينطبقُ عليهِ عروجٌ او صعود, او انتقالٌ او هبوط او ارتفاعٌ او اِنزالٌ او تنزيل وهو ليس فوقٌ وليس تحت.\nفالكونُ في تكوينهِ نسبيٌّ مَحدودٌ بالزمانِ والمكانِ واللهُ مُطلقٌ في ذاتِهِ, وجودُهُ ذاتيٌّ مُستغنٍ عن غيرهِ, ولكنّ وجودَ الاكوانِ حادثٌ يفتقرُ الى اللهِ ويقومُ بقوتِهِ.\nفهوكانَ على ما كان قبلَ خلقِ المكان ولا يتغيرُ عما كانَ, عَلِمَ ما كان وما يكونُ وما لايكونُ ولو كان كيف يكون فهوما وراءَ كل شيءٍ ليسَ كمثلِهِ شيء وهو السميع البصير.", "/images/products/9786339970399.webp", "9786339970399", "جبرئيل المخلوق الأعظم والملأ الأعلى (الأنبياء و النبيون)", null, 400m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 431, "أمل القادرى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في قلب العاصفة، وُلدت سديم… نصف عرّافة، نصف لعنة.\n\nلم تكن تعرف أن دقات قلبها ترتبط بنبض كائن آخر…\nذئبٌ يتربص بروحها، ويشدّها إليه بحبل من دم لا ينقطع.\n\nقُدّر لها أن تكون فريسة ونبوءة،\nعاشقة وغنيمة.\nوبينما العالم ينهار من حولها، كان هو الوحيد القادر على انتشالها… أو دفعها نحو الجنون.\n\nقوةٌ غامضة تنمو في عروقها،\nرغبةٌ لا تعرف الرحمة تنمو في عينيه.\nوسؤال واحد يتردّد في ظلالهما:\nهل يُمكن للحب أن يولد من اللعنة؟\n\nسديم الباروك، عرافة الألفا\nرواية عن رابطٍ أبدي لا يُكسر… وعن صراع يتجاوز السحر والدم، إلى ما هو أعمق: الروح.", "/images/products/9786339971006.webp", "9786339971006", "سديم الباروك", null, 300m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 432, "هالة حمدى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هواء ثائر يعبث بردائهم السابغ الذي يلامس أحذيتهم، تتأرجح قلنسوة الرداء فوق جباههم بقوة وكأنها تغربل الأفكار وتحسم القرارات.\nكلاهما غافلان عن ميل الشجرة عن يمينهم وقد أوشك الهواء على اقتلاعها، ما تجابهه أفكار هم أقوى وأقسى.\nلنتركه لربما عاد إلى رشده، ونكون قد احتوينا فرداً جديداً وكنا عوناً له على نفسه.\nمن سرق تقطع يده ليكون عبرة لمن بعده، اليوم سرق، وفي الغد يقتل، من استباح شيئاً ليس من حقه عليه عقوبة وإلا سيتمادى بلا رادع.\nاختلاف جذري بين آرائهم التي جُبلوا عليها، وكان أحدهم أخذ من سماحة المياه في انسكابها، والآخر أخذ من تعلق الصوف بالسيخ منهجاً.\nيهدأ الهواء حولهم لتستقر الشجرة وتستقيم عن ميلها\nلنمرر الأمر.\nوماذا عن تلك العين المراقبة، ألن تسأل عن القاتل، ألن تحيك الشباك للقصاص منه.\nستلهيه الحياة بما فيها من مصاعب.\nبل ستكون تلك هي أول المصاعب، وربما تكون الأصل الذي ستدور حوله حياته.\nيتحدثان من خبرتهم على مر العصور، لا يتذكر أحدهم كم عمره، ولماذا يعيشون في تلك المنطقة النائية تُعرض عليهم الأقدار ليخوضوا نقاشاً متكرراً لم يضع أحدهم حتى الآن نهايته", "/images/products/9786339971037.webp", "9786339971037", "يوم حلت العقد", null, 250m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 433, "بدور عادل", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أنت في( ندينجي) حيث الخطيئة هي الأصل والتوبة منبع الشرور.\nأنت في (ندينجي) فيها يصبح إلهك هواك، دنس روحك هو طريقك إلى القمم، وآثامك هي راحلتك إلى ما تصبو.\nأنت في (ندينجي ) حيث مُحِيّ نور النفوس وشاع ظلامها.\nأنت في( ندينجي) حيث فُرخت الشهوة، عُبدت الرذيلة، وقُدس المال وأصبح كل حرام مباح.\nأنت في (ندينجي) حيث يتوضأ العجائز بالدماء وتغتسل العذارى بالخطايا.\nأنت في (ندينجي)\nفلا أهلًا ولا مرحبًا..", "/images/products/9786339971099.webp", "9786339971099", "ندينجي", null, 250m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 434, "نشوة أبوالوفا", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بعد أن وقع العالم تحت وطأة الكورونا انقلبت كل الأمور رأسًا على عقب!\nظهر ابتلاء لا قِبل للبشر بمواجهته، في محاولات لإيجاد مخرج من ذلك الابتلاء تدور الصراعات.\nفهل سينتصر البشر؟!\nأم يندثرون تحت الثُرى مسطرين نهاية الكوكب الذي نعرفه؟!", "/images/products/9786339971044.webp", "9786339971044", "زوشادو", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 435, "هانى الغيتاوى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يُداوون أنفسهم من الهموم والأحزان، يفتحون لأنفسهم طرقاً يسلكونها يلتمسون فيها معاني الصبر والسلوان على ما ألمّ بهم من ملمات وأحزان، لذلك عندما تراهم تجدهم باسمين متطلقين، وكأنهم لا يُعانون من شيء، ولو تركوا مساحة لتطلع على حقيقتهم لوليت فراراً ولمُلئت نفسك من أجلهم حزناً وهماً وكمداً.\nهم ولا شك صفوة الناس، فرغم ما يثقلهم من هموم وأحزان، تكلفوا السرور، حتى لا يُسببوا لغيرهم التعاسة، ولا يُصدّرون لهم اليأس والقنوط.\nهؤلاء يُشرفون على الحياة والابتسامة عالقة على ثغرهم لا تفارقهم، يُقبلون على الدنيا متطلقي الوجه، يراهم الرائي فيغبطهم على حالهم، مغتراً بابتسامة ثغرهم وتطلق وجههم، ربما لو أمعن هذا الرائي قليلاً، وكشف عن أنفسهم، ووجوههم الباسمة المتطلقة لاسترد غبطته إلى نفسه، وترشف من القناعة ترشفاً تجعله يرضى عن حاله.", "/images/products/978633991068.webp", "978633991068", "تأملات الفكر و الخاطر", null, 250m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 436, "نشوة أبوالوفا", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدور أحداث الرواية عن الصراع ما بين القلب والعقل وحرب ما بين العادات ومواطن القوة والعزة في النفوس، عادات قديمة من الاعتزاز فقط بالذكر وتهميش واحتقار كامل للأنثى، فهل سيفرض القلب والرحمة سطوتهما أم يندثران تحت وطأة ظلم العادات الموروثة؟", "/images/products/9786339971075.webp", "9786339971075", "رقص على الجمر", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 437, "هانى الغيتاوى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هكذا هم الدهماء أو السواد الأعظم من الناس، الذين يُسطّرون ملاحم بطولية كل يوم.. هي تجارب إنسانية يزدحم بها وعاء الزمن، لكن لبساطة أصحابها، لا يتوقف عندها التاريخ؛ لأنه يرى فيها تجربة إنسانية لا تستأهل التوقف عندها، فما الذي يغري التاريخ في عامل أو موظف بسيط يُبكر لعمله سعياً على الرزق ليقيم أوده، ويَسُدّ رمق أولاده؛ ليعيشوا حياة كريمة.\n​يتحمل مشاق الحياة ومرارتها، لا يطمع في جاه، ولا يروم منصباً، ولا يأمل في سلطة، غايته الستر له ولأولاده، وكذلك ملايين الأحداث التي تدور رحاها تحت شمس الحياة، كفقير متعفف لا يسأل الناس إلحافاً، أو مسكين لا يستجدي أكف الناس، يربأ بماء وجهه أن يُراق، أو غارمة نكبها الدهر، تسعى في مناكب الأرض ومخارمها، تعمل وتجدُّ، وقد تقرّح ذهنها من همّ التفكير في كيفية سداد ديونها، وما أن يسدل عليها الليل سدوله حتى يُقضّ مضجعها مذلة هذا الدَّيْن، ورغم ذلك كله تجدها بثغر مبتسم، ووجه منطلق حتى تُخفي ما ألمّ بها عن أولادها؛ كي لا تُسبّب لهم ضيقاً أو ألماً.\n​ومهما أتعلم فلا أزال جهولاً\nد. هاني الغيتاوي", "/images/products/9786339971082.webp", "9786339971082", "ومهما أتعلم فلا أزال جهولا", null, 250m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 438, "روزان إبراهيم", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إنها تنتظر شخصا ما تعتقد أنه سيأتي إليها\nستعرف الألم والخيانة، حتى تتمنى الموت بدلا من النوم", "/images/products/9786339971709.webp", "9786339971709", "رانشيرو", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 439, "علاء محمود حسين", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "العمل بيتناول طرق الربح من الإنترنت وإزاى ممكن تزود دخلك وتخلق لنفسك فرصة عمل عن طريق الإنترنت واستخدام مواقع التواصل الإجتماعي.", "/images/products/9786339971754.webp", "9786339971754", "الربح من الإنترنت", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 440, "حجازى الرفاعي", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "حين يدرك الإنسان أن كل تصرف يفعله يؤثر في بيئته المحيطة ومجتمعه الكبير ؛ثم يتأثر هو نفسه بهذه السلوكيات بصفته فرد من أفراد المجتمع ؛سيحسن من سلوكه، وبذلك نعيش حياة سعيدة.\n\nلكل مجتمع طباع وعادات تتحكم في سلوك الأفراد وتؤثر في طبيعة العلاقات بينهما ، فمن هذه العادات صفات حميدة يجب دعمها ،ومنها سلوكيات مرفوضة يجب الإنتباه لها وتجنبها.", "/images/products/9786339971761.webp", "9786339971761", "أبسط من لهيب الشمس", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 441, "إلهام محمد عوض", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذا الكتاب ليس وعدًا بزوال العواصف، بل بصيرة تُعلِّمك كيف تقف ثابتًا حين تعصف، كيف تُنصت لنفسك، وتفهم ابتلاءك، وتخرج من الانكسار أكثر وعيًا لا أقل ألمًا.\n«حين تهدأ العاصفة» رحلة هادئة نحو الرضا، وفهم الحكمة الخفية، والقيام من جديد دون أن تفقد إنسانيتك.", "/images/products/9786339971785.webp", "9786339971785", "حين تهدأ العاصفة", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 442, "وليد الدسوقى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "اليوم واليوم فقط أشعر بمذاق الحرية ، لساني\n‏أصبح طليق و ارتاح ظهري و كاهلي من الأحمال التي لا أطيق.\n‏أعلم كم ستتعجب عندما تقرء صفحاتي و ربما\n‏تشمئز من خط يدي المتعرج ولكنها السنين قد\n‏هزت جزعي و ألحقت رعشة بسيطة بيدي.\n‏ستغفر لي تلك الرعشة عندما تعرف ما ألم بي ..\n‏أنا متأكد من أنك ستكون الوحيد الذي يصدقني\n‏أيها الغريب.\n‏\n‏ توقيع : فهمي بك غريب", "/images/products/9786339971792.webp", "9786339971792", "أيام في المنفى", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 443, "رضا عابد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كتاب تربوي إرشادي موجه للأمهات ومقدمي الرعاية – تعديل سلوك الطفل (من 3 إلى 6 سنوات)\nاقتباس / فكرة عامة تجذب الجمهور:\nلأن الطفل لا يسيء التصرّف عنادًا، بل يصرخ طلبًا للفهم…\nهذا الكتاب دليل عملي يساعدكِ على فهم سلوك طفلك في سن الحضانة، ومعرفة أسبابه الحقيقية، والتعامل معه بهدوء ووعي دون صراخ أو عقاب مؤذٍ. خطوات بسيطة، مواقف واقعية، وأدوات تربوية تساعدكِ على بناء شخصية متوازنة لطفلك، وتعيد الهدوء إلى بيتك.", "/images/products/9786339972102.webp", "9786339972102", "الدليل العملى لتعديل سلوك الطفل في سن الحضانة", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 445, "إلهام محمد عوض", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذا الكتاب مساحة آمنة لمن أثقلهم التعب، وكتمت أرواحهم الزفرات طويلًا.\n«تنفّس مجددًا» ليس دعوة للنسيان، بل للتخفف، لترميم الداخل، ولمنح القلب فرصة أخرى للحياة بعد الانكسار.\nهو رسالة هادئة تقول: لا بأس أن تتعب، المهم ألا تنسى أن لك حقًا في الراحة… وفي البدء من جديد.", "/images/products/9786339972133.webp", "9786339972133", "تنفس مجدد", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 446, "داليا نور", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "«كتبت هذه الرواية لأنني أؤمن أن الحنين لا يكون لإنسانٍ وحده،\nولا لوطنٍ وحده…\nبل لذلك الشعور الغامض الذي يشبه الاثنين معًا.\nللحب حين يصير بيتًا،\nوللوطن حين يصير قلبًا نابضًا في الصدر مهما ابتعدنا.\nعن انتظارٍ طال، وعن غربةٍ علّمتنا أن بعض البشر أوطان،\nوأن بعض الأوطان لا تعود أرضًا فقط… بل تعود روحًا.\nحنين حب،\nحنين وطن،\nحنين إنسان وجد نفسه أخيرًا حيث يجب أن يكون.»", "/images/products/9786339972140.webp", "9786339972140", "مرافئ الحنين", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 447, "إسراء ساهر", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "“عقدان من الزمن” ليست رواية للقراءة السريعة،\nبل تجربة شعورية لكل من مرّ بسنوات ثقيلة، وخرج منها مختلفًا… لكنه حي\n\n“لم أخرج من عشرين عامًا كما دخلتها… تركت فيها طفولتي، وأخذت معي نفسي.", "/images/products/9786339972157.webp", "9786339972157", "عقدان من الزمن", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 449, "سارة سامى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "عذرًا إني أحببت…\nلأن الحب أحيانًا لا يكون اختيارًا، بل تضحية.\nحكاية عن قلبٍ اختار أن يخسر نفسه كي لا يخسر عائلته،\nوعن مشاعر صادقة وُضعت في مواجهة الواجب،\nفكان الصمت أثقل من الاعتراف،\nوالبعد أرحم من البقاء.\nرواية تناقش حين يصبح الحب اختبارًا للإنسانية،\nلا انتصارًا للعاطفة وحدها.،", "/images/products/9786339972171.webp", "9786339972171", "عذرا أنى أحببت", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 450, "سليمان محمد أبوليلة", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لم تكن جهود أئمة الحديث الأوائل في تأسيس قواعد علمي الإسناد والجرح والتعديل ترفا فكريا، بل كانت ضرورة شرعية قصوى الحماية الدين وصيانته. يقدم لك هذا الكتاب\nخلاصة قيمة لهذه الجهود؛ لتكون على بينة من أمرك وتشارك بفعالية في حفظ هذا الدين وتبليغه نقيا كما وصل إلينا من النبي صلى الله عليه وسلم.", "/images/products/9786339972188.webp", "9786339972188", "الحديث الموضوع وأماراته", null, 100m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 451, "محمد نجيب مطر", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "اسم الكربون الأسود سيظل محفورًا في ذاكرة التاريخ لهؤلاء الرجال الذين ضحوا بالكثير من أجل مصر، خيرت، عبد القادر، وثروت.\nأقاموا جسرًا من الخفاء إلى الضوء، حيث لا يعرف سوى قلة قليلة الحقيقة الكاملة حول ما جرى.\nلكن التاريخ يذكرهم كرجالٍ شجعان، عملوا دون انتظار مكافآت أو أضواء، من أجل وطنهم، كانوا في قلب المعركة الكبرى، وفي نهاية المطاف، كانت مصر هي المستفيد الوحيد من تضحياتهم.\nهذه القصة تبرز كيف أن هناك رجالًا عاشوا في الظل، وضحوا بكل شيء من أجل أمن وطنهم.\nلقد حملوا على أكتافهم مسؤولية كبيرة، وعندما لزم الأمر، كانوا مستعدين لدفع الثمن، فالتاريخ لا ينسى مثل هؤلاء الرجال الذين عملوا بإخلاص للوطن، بعيدًا عن الأضواء والأنظار.", "/images/products/9786339972546.webp", "9786339972546", "الثعلب والكربون الأسود", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 452, "محمد نجيب مطر", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدريجياً، بدأ الحاج محمد يستعيد اهتمامه بالحياة. أصبح يخرج مع حفيده إلى الحديقة، ويشتري له الحلوى، ويحكي له قصصاً مسلية. بدأت الابتسامة تعود تدريجياً إلى وجهه الشاحب.\nلم يعد الحاج يشعر بالوحدة القاتلة التي كانت تسيطر عليه. وجد في حفيده سلوى وعزاء، وفي زوجة ابنه منى، ابنة بارة وصديقة وفية، أدرك أن الحياة لا تتوقف عند فقدان الأحبة، وأن هناك دائماً بصيص أمل ونور في نهاية النفق.\nصحيح أن جرح فقدان ابنه سيظل غائراً في قلبه، لكن وجود حفيده وزوجة ابنه منحه سبباً جديداً للاستمرار، وذكّره بأن الحب والعائلة هما أقوى من قسوة الفقد والوحدة.\nوهكذا، استطاعت زوجة الابن الوفية أن تعيد الحياة إلى قلب الأب الحزين، وأن تحول شقة الفقيد إلى بيت دافئ يملؤه الحب والأمل من جديد.", "/images/products/9786339972195.webp", "9786339972195", "مغامرات ياسين ومحمود العلمية", null, 100m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 454, "غادة حاتم مصطفى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "رأى غيث اليأس يتسلل إلى وجوه الجميع، حتى العم زكريا الذي كان صامدًا. في تلك اللحظة، تذكر كل لحظة فشل في حياته، كل يأس، كل كلمة قيلت له بأنه \"لن يفلح\". لكن الآن، بعد أن رأى نور الإيمان ينبعث من داخله، وبعد أن فتح \"ختم الوعي\" بكلمات الله، شعر بقوة غير مسبوقة.\n\"لا تيأسوا!\" صاح غيث فجأة، صوته يصدح في القاعة وكأنه صرخة أمل في وجه الظلام. \"لقد كنتُ هناك! في قاع اليأس، في ظلام الفشل! لم أحقق شيئًا في حياتي! كنتُ أظن أني ضائع إلى الأبد. لكن الله، برحمته، لم يتركني!\"\nنظر إلى سارة، ثم إلى كل منهم، وعيناه تلمعان بالصدق. \"لقد علمنا أن النية الصادقة تفتح الأبواب المغلقة. أن الصبر يهزم الصعاب. أن التوكل على الله يجعل المستحيل ممكنًا!\"\nتذكر قول الله تعالى: ﴿قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنفُسِهِمْ لَا تَقْنَطُوا مِن رَّحْمَةِ اللَّهِ ۚ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا ۚ إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ﴾ [الزمر: 53].\n\"يا من شعر بالفشل، يا من لم يحقق شيئًا منذ القدم، يا من ظن أنه لا أمل فيه! الله لا ييأس من عباده! ليست النهاية ما تراه العين، بل ما يقرره القلب. قم! انفض غبار اليأس، واعلم أن كل يوم جديد هو فرصة لميلاد جديد، وأن أعظم النجاح ما يأتي بعد سقوط مُدَوٍّ.\"\nكانت كلماته كالصاعقة، تضرب قلوبهم، وتبث فيهم روحًا جديدة. سارة نظرت إليه بإعجاب عميق، حبها العفيف له يزداد رسوخًا.", "/images/products/9786339972515.webp", "9786339972515", "أسرار أطلانطس", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 455, "أحمد جمال سليمان", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لقد استترت الأوجه خلف أقنعةٍ مزيّفة، لتحجب حقيقتها الماكرة الخادعة التي تنطلي على أذهان المساكين، كمن يلوِّح بأضواءٍ زاهيةٍ ليواري وراءها ظلامًا حالكًا. ترى صورتك القديمة في مرآتك؛ فترى مظلمة سوداء لا تعكس شيئًا! فقط الظلام هو صورتك! هو أنت تُدفن الأفعال الدنيئة الرخيصة في باطن آبار الخيرات والمسرّات، تتخذ من السعي إلى الصلاح ستارًا، لكنها ليست سوى مسرحيةٍ منسوجة بخيوط الشرّ والخداع. فما تراه الناس خيرًا، هو في الحقيقة شرٌّ مستتر، والمسرّات ما هي إلا وجوه زائفة لحزن دفين يقبع في الأعماق، والصلاح لا يعدو كونه طالحًا مغلّفًا بغطاء من الوهم! هذه الحكاية تسلّط ضوءها على ظلال الأكاذيب، تفتّش بين خفاياها عن حقائق تبدو بريئة، ولكنها في جوهرها أوهام دفينة محكمة البناء. إنها الحكاية التي تطيح بعقول البسطاء بلا هوادة! تُخضعهم وتخدعهم لتصديق الكاذب ومنح الأمانة للخائن، دون أن يكون لهم ذنب في ذلك. فكيف للإنسان أن يرى الحقيقة، إذا كانت العيون لا تبصر سوى الأقنعة؟ ليست هذه الكلمات هذرًا، بل إعلان لجديّة حاسمة، تتغلغل في أعماق النفس لتكشف هشاشتها أمام الزيف، وتجعلنا نتساءل: أيمكن أن يكون الخير والشر وجهين لعملة واحدة، أم أن العالم بأسره مسرحٌ يتبادل فيه الأقوياء أدوار الطغيان؟ ولكن هذه الحقيقة التي تظهر من فينةٍ لأخرى، ومنذ بدء الخليقة فقد أودع فيهم الربُّ حبُ الخير والشر، والتناقضات الفكرية، والانحدارات الأخلاقية، وما سيُقال ما هي إلا إسقاطات لحكايات لأشخاص صاروا طعامًا يُستساغ بين أشداق الماضي. والذي تراه ملاكًا بريئًا وديعًا يرفرف بكلتا جناحيه، ما هو إلا شيطان يقبض بيده على صولجان ليدسه في قلبك!", "/images/products/9786339972522.webp", "9786339972522", "المرأة المظلمة", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 456, "إسراء ساهر", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ماذا لو كانت أقسى سنوات عمرك… هي نفسها التي صنعتك؟\nهذه الرواية لا تحكي عن بطلة خارقة، بل عن فتاة عادية وُضعت في اختبارات أكبر من سنها، فتعلمت أن تنضج قبل أوانها.\nبين ظلمٍ دراسي، وفقدٍ لا يُشفى، وغربةٍ سرقت الطمأنينة، ومسؤولية جاءت مبكرًا… تمشي البطلة في طريق طويل لا يحمل وعودًا واضحة.\n\nلكن حين تتعطل الحياة فجأة، قد تمنحنا أكثر مما سلبته.\nحب يولد من صدفة، وبيت يُبنى من التعب، وقلب يتعلم أن يختار السلام بدل التمسك بالماضي.", "/images/products/9786339972539.webp", "9786339972539", "عقدان من الزمن (الجزء الثانى)", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 457, "على مهران", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الجدة توتي شيري تعود إلى الحياة لتروي لنا حكايات مفيدة للمصريين\nوتشجعنا على التحلي بتلك الصفات الحميدة، كما تشجعنا على التمسك بالقراءة لما لها من أهمية.", "/images/products/9786339972553.webp", "9786339972553", "الجدة تروى", null, 100m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 458, "جنه إسماعيل", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تتحدث الرواية عن خمسة أبناء خالة وجدوا سلسلة على شكل نجمة خماسية وعلموا أنها وقعت من شخص يدعى يونس ماتت خطيبته وسلك طريق السحر وذهب لعالم القرائن، وهؤلاء الخمسة وجدوا هذه السلسلة ما الذي سيواجهه هؤلاء الأولاد هذا ما ستحكيه لنا الرواية.", "/images/products/9786339972560.webp", "9786339972560", "البوابات النجمية", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 459, "جنه إسماعيل", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تحكي الرواية عن عالم فضاء اكتشف كوكب جديد فصنع سفينة فضائية وسافر دون معرفة أحد إلى هذا الكوكب الجديد ليكتشف مايوجد فيه، وهلى سبجد عليه احد أم ما الذي سينتظره هذا في هذا الكوكب.", "/images/products/9786339972577.webp", "9786339972577", "كوكب الحيوانات المجنحة", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 460, "إيمان محمد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يُعد هذا الديوان الذي يضم بين دفتيه قصائد لم تكن سوى لحظات من حياة، خطّتها اليد حين فاض القلب بالحب أو الحزن، بالفرح أو الألم، باليأس أو الأمل فإنه يحمل حروفاً وكلمات في طياتها أصداء تجارب إنسانية عميقة، ولدت من رحم التأمل في الحياة، وفي تفاصيلها الدقيقة. آمل أن تجد في كل قصيدة صدىً يلامس روحك، وأن تضيء لك شمعة في عتمة الطريق، أو تروي عطشاً في صحراء الحياة", "/images/products/9786339972584.webp", "9786339972584", "خلف أسوار القلب", null, 100m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 461, "كرم الشافعى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "قطار حياة الإنسان بمر بمحطاتٍ كثيرة متلاحقةٍ\nمنها محطاتٌ حلوةٌ عذبةٌ، ومنها محطاتٌ مالحةٌ مرةٌ.\nمنها محطاتٌ يقبل عليك فيها أكثر الناس، ومنها محطاتٌ ينفض عنك فيها كل الناس.\nمنها محطاتٌ ينعم الله فيها عليك بأعظم النعم، ومنها محطاتٌ تلفحك فيها سياط العدم.\nمنها محطاتٌ تنعم فيها بعاطفة الحب والود من الناس، ومنها محطاتٌ تؤلمك فيها مشاعر الجفاء والبعد من أكثر من عرفت منهم.\nمنها محطاتٌ يبتسم لك فيها الكبير والصغير، ومنها محطاتٌ يعبس في وجهك فيها كل قريبٍ وحبيبٍ.\nيمر الواحد منا في حياته بمحطاتٍ كثيرةٍ، أحداثها متلاحقةٌ، ومن كل محطةٍ يتعلم الإنسان درسًا بليغًا قاسيًا ورائعًا، من عظيمٍ من العظماء، تلك هي الحياة المعلمة، كما أشار الله إلى تقلباتها المستمرة في القرآن الكريم فقال فيها: (والله يعلم متقلبكم ومثواكم) في إشارة إلى أن الله عليم بكل أحوال الناس في حركاتهم وسكونهم، في حياتهم الدنيا وفي مصيرهم في الآخرة، وقد أقسم سبحانه على ذلك فقال: (فلا أقسم بالشقق والليل وما وسق والقمر إذا اتسق لتركبن طبقًا عن طبق) أي لتتحولن من حالٍ إلى حالٍ، مما يدل على أن الحياة مليئةٌ بالتغيرات والتقلبات، والإنسان ينتقل فيها من الطفولة إلى الشباب، ومن الشباب إلى الكهولة، ومن الصحة إلى المرض، ومن الغنى إلى الفقر، ومن السعادة إلى الحزن، وتلك محطاتها المتعددة.\nوالعارفون بطبيعتها، والفاهمون لتقلباتها، والراضون بها على كل أحوالها، وهم يسيرون فيها هم أكثر الناس سعادةً بها،\nهذا موضوع كتابي الذي بين أيديكم الآن: (علمني هؤلاء)، أقدمه للقارئ الكريم وأحتسب فيه الأجر من الله تعالى، وأسأل سبحانه أن يكون جهدي فيه خالصًا لوجهه الكريم، إنه ولي ذلك والقادر عليه.\nالفقير إلى عفو ربه", "/images/products/9786339972591.webp", "9786339972591", "(أحببت هؤلاء) 30 عظيما علمونى فن الحياة", null, 200m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 462, "محمد عماد", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "حين ينتشر الظلام ، يبدأ عالم آخر في البزوغ ..\nعالم تمتلئ فيه الأفكار بالتوتر ، وتتحول الأماكن المألوفة إلى مصائد غامضة .\nأصوات مجهولة ، أشياء تتحرك من تلقاء نفسها ، وأبواب لا تؤدي إلا إلى هاوية أعمق .\nليس الرعب فيما تراه عيناك ، بل فيما يتربص بك خلف السكون .\nهذه الصفحات ليست للقراءة فقط ..\nإنها تجربة ستبقى معك طويلًا بعد أن تطويها ..", "/images/products/9786339974014.webp", "9786339974014", "أوراق ملعونة", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 463, "مصطفى الشيشتاوى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "خمس حكايات تتقاطع فيها الطرق بين الضوء والعتمة، بين العقل والجنون، بين الإنسان وظله.\n\nفيها ستسظل بموت الحب وخيانة الموت..\nستتوارى من عشقِ الجن، وتهرولُ من فصامِ النفس، وتفزعُ حين تُبصرُ فتاة الجامع واقفةً عند باب قلبك... لتجد رأسك أخيرًا معلَّقًا في حبل مشنقةٍ داخل سجن الاستئناف.\n\n\"عملٌ يعرّي الإنسان أمام مرآة روحه، لذا إحذر ولا تنفعل مما ترى\"", "/images/products/9786339974021.webp", "9786339974021", "السيد: ميم", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 465, "حبيبة عماد غريب", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ما بين السطور… كواليس لا تُروى، وحكايات لا يمكن أن تُفهم كما كُتبت… لأنها لم تُكتب أصلًا لتُفهَم، بل لتُنقذ شيئًا صغيرًا، كان يوشك أن ينطفئ.\nبعض الأرواح تختبئ في القصص، لا لتُكتشف… بل لتبقى حيَّة.", "/images/products/9786339974052.webp", "9786339974052", "خارج عن النص", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 466, "حسين أحمد حسين حسن", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"تعجب حسن لما قاله السائق، وقال محدثًا نفسه: ليس هناك قانون واحد من الآن، فكل فرد وضع لنفسه قانون. ولم تمر أيام كثيرة حتى وجد مدير الشركة يفصل كل من تسبب في حث الموظفين على الإضراب والاعتصام عن العمل، ولم يعرف أحد ما تأثيرات الثورة بعد ذلك.\"", "/images/products/9786339974069.webp", "9786339974069", "القاتلة", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 467, "أمينة الريحانى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدور أحداث الرواية حول شهاب الصفدي الذي كان معروف بعلاقاته النسائية هو وصديقه الوحيد مازن الحسيني ، إلى أن ارتبط شهاب عاطفيا بكارما أخت مازن الوحيدة والتي أحبها حبا شديدا وقرر أن يغير كل حياته من أجلها ، إلا أن حدث بينهما موقف جعلها تظن أنه يخونها ، فتقرر أن تتركه وتسافر بعيدا ، ظل شهاب يبحث عنها كثيرا على مدار سنوات ولكن دون جدوى ، ليظل طيفها الذي يأتيه من وقت إلى أخر هو الونيس الوحيد له والذي يشعره بأنها مازالت بجانبه تشعر به ، ظل شهاب على حبه لكارما إلا أن اضطرته الظروف إلى خطبة نيفين ابنة عمه ، الذي قام يخطبتها لينقذها من أمر ما ، ولكنه ظل على حبه المعروف للجميع لكارما ، لتدخل بعدها علياء حياته ويشعر أن قلبه بدأ يميل إليها ، فيقرر مازن الذي أحبها هو الاخر أن يغير مجرى قصتهم ، ليتفاجأ شهاب بعودة كارما وتكون المفاجأة التي زلزلته ووضعته بين امرين محيرين بينها وبين علياء التي تعلقت به بشدة ، خاصة بعد أن علم أن سبب بعد كارما عنه كل هذه الفترة هو دخولها في غيبوبة بعد تعرضها لحادث، وأن ما كان يراه هو روحها وطيفها يناديه ، وفى الوقت الذي قرر شهاب أن ينهى قصته مع علياء ليعود إلى كارما ، تكتشف كارما علاقته بعلياء وخطبته من نيفين وتفاجأه برد فعلها .", "/images/products/9786339974076.webp", "9786339974076", "الطيف", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 468, "سمر إسماعيل دسوقى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "فداعبتها ذات مرة في وجود زميل لها، أن لكل طالب ما يشغله ويعطله عن الدراسة والتحصيل العلمي، فزميلها هذا قد كان يعطله النت والكمبيوتر ، أما هي فأعتقدها مشغولة بأنوثتها المتفتحة كالزهرة النضرة في غضون الربيع", "/images/products/9786339974090.webp", "9786339974090", "الحب في زمن الكورونا", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 470, "عمرو زاهر", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "عزيزي القارئ، كتبت هذا الكتاب من الألم، ونسجت حروفه من خيبات الأمل ، وجمعت الأمل فيه من كثرة التردد، ورتبت أبوابه من كثرة التخبط والإحباط.\nتعلمنا فيه كيف نعرف أنفسنا بشكل صحيح، ونحترم ماضينا، ونستمتع بحاضرنا ، ونحن نخطط للمستقبل، تخطينا فيه كل حاجز يحول بيننا وبني سلامنا النفسي مع أهلنا ومع الله ، حتى وصلنا الي ما يجب فعله مع الاخرين لننعم بسلام نفسي حقيقي.\nولنصل لهذا السلام يجب أن تعرف أن بداية كل تغير هو الألم ، والخروج من منطقة راحتنا،\nوالنهوض من تحت سقف غرفتنا؛ لنعيش حياتنا كما يجب أن تكون.\nولنرتك خلفنا في كل ريع آيًة باسمنا، لا لنعبث، ولكن لتخبر من يأيت بعدنا أننا كنا هنا.", "/images/products/9786338367015.webp", "9786338367015", "لا من أجل سلامك النفسى", null, 250m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 472, "إسراء مظلوم", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في زمنٍ قديمٍ ومكانٍ ساحرٍ يُدعى \"سيرانو\"، كان السلامُ يعمُّ فيها بسببِ ملكِها المغوارِ، ولكن بسببِ قانونٍ خُطَّ قلبَ الأمورَ رأسًا على عَقِبٍ.\nولكن لم ينتهِ الأمرُ عند هذا الحدِّ، بل هناك من دفع ثمنَ خطيئتِه.\nولم يعلمْ أنها شرارةُ عودةِ سيرانو إلى عهدِها القديم،\"عهدٍ منذُ الأزل\".", "/images/products/9786338367039.webp", "9786338367039", "سيرانو عهد منذ الأزل", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 473, "أم محمد عياطىي", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "وانطلاقًا من هذا الواقع المرير الذي يشتكيه عشاق النحو وطلابه، ارتأيتُ أن أقدّم بعض الطرق اليسيرة لتقريب الإعراب، فوضعت أهم أساسيات النحو ضمن دروس تطبيقية، بعيدًا عن التنظير الجاف والأسلوب السردي العقيم الذي يجعل الطالب يدور في حلقة مفرغة، ليعود من حيث أتى فارغ اليدين.", "/images/products/9786338367046.webp", "9786338367046", "تعلم الإعراب بدون معلم", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 474, "إسراء عرفة", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كتاب علمي مبسط عن مرض السكري (Diabetes Mellitus) موجه للأمهات، المقربين من الطفل السكري، وللمرضى الكبار أيضًا، مع جزء مخصص للمثقفين السكريين وأخصائي التغذية.", "/images/products/9786338367053.webp", "9786338367053", "سكر زيادة", null, 1200m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 476, "وئام عادل", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أساطير من أرض الأندلس\nفي أرضٍ غمرها السحر والتاريخ، حيث تتعانق القلاع مع الغيوم وتختبئ الحكايات في صدور الأنهار، تولد الأساطير…\nهنا، ليلى بنت القاضي التي حملت الأندلس على كتفيها لتمنع سقوطها، والقائد عمرو الذي ألقى بسيفه أمام قلبٍ أسيرٍ فاختلط الحب بالدم.\nوهنا أمّ صنعت التاريخ حين غرست البطولة في ابنها، وفارس غامض خرج من رحم الظلال ليقلب موازين الحروب.\nوفي النهاية… تأتي ياسمين، الصحفية القادمة من زمننا هذا، لتجد نفسها عالقة بين أسوار الأندلس، في قلب صراعٍ لا يرحم، وحبٍ يتحدى الزمان والمصير.\nأساطير من أرض الأندلس ليست مجرد قصص… إنها عبور إلى عالم آخر، حيث التاريخ يشتعل، والعاطفة تصرخ، والخيال يفتح أبوابه على مصراعيها.\nكتاب يسرق أنفاسك منذ الصفحة الأولى… ويترك قلبك أسيرًا حتى آخر سطر.", "/images/products/9786338367084.webp", "9786338367084", "أساطير من أرض الأندلس", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 477, "مروان العلان", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "قصة حب بين رجل ستيني عربي وباحثة إيطالية يلتقيان صدفة في رحلة باتجاه شرق آسيا. هو حانق على واقعه وهي سائحة..", "/images/products/9786338367091.webp", "9786338367091", "مانشوكا", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 478, "مروان العلان", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يهرب الأستاذ الجامعي من ضغط الحياة ويلتقي بامرأة يكتشف مدى توافق شخصيتها مع شخصيته فيتفقان على الهروب من المجتمع بإقامة مشروع خارج المدن ما يلبث أن يتحول لمقر للعزلة والحب والابتكار العلمي.\n\nيتكوّن هذا الكتاب من 4 أجزاء: واعدة، واعدة (الجزء الثانى)، واعدة (الجزء الثالث)، واعدة (الجزء الرابع).", "/images/products/9786338367107.webp", "9786338367107", "واعدة", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 479, "شهد أحمد إبراهيم", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في عالم حيث الحب هو الميزان الذي يحدد مصائر القلوب، تأتي \"ندبة العمر\" لتروي قصة \"تاج\" و\"حيدر\"، قصة حب كُتبت بدموع الشغف ورُسمت على صفحات الألم والخيبة. إنها ليست مجرد حكاية عابرة، بل هي رحلة عميقة في تضاريس المشاعر الإنسانية، تكشف كيف يمكن للحب أن يكون النور الذي يضيء أعتى الظلمات، والندبة التي تحفر في الروح عمقًا لا يُمحى.\nتاج، الفتاة التي لم تتوقع أن يكون قلبها ساحة لحرب تخوضها روحها، وحيدر، الذي اكتشف متأخرًا أن الحب ليس مجرد نظرة أو وعد زائف، بل التزام ينبعث في أحلك اللحظات. يواجه الاثنان قدرًا قاسياً، حيث تنكسر الوعود وتتلاشى الأحلام تحت وطأة الغياب والخذلان، وتُفرض قيود العادات والتقاليد لتُشعل معركة بين الحب والالتزام.\nتتنقل الرواية ببراعة بين أصداء السعادة الغامرة التي يسبقها الحب، وبين وحشية الفراق والخيبة التي تترك ندوبًا لا تندمل. من خلال مونولوجات داخلية مؤثرة ولغة شعرية تلامس الوجدان، تعكس \"ندبة العمر\" صراع البطلة مع الألم والندم، وكفاحها لتحقيق انتصار شخصي حتى وإن جاء الثمن باهظًا. هل يمكن للحب أن يصلح ما كسره الغياب؟ وهل يمكن للحياة أن تمنح فرصة لمن غابت عنها العدالة؟\n\"ندبة العمر\" ليست مجرد رواية، إنها قصيدة ألم وأمل، صرخة قلب مجروح يحكي قصة التضحية، النسيان، والندم الذي يطارده القدر. إنها دعوة للتأمل في قوة المشاعر البشرية، وكيف يمكن لحدث واحد أن يغير مسار العمر ويترك بصمة لا تُمحى.", "/images/products/9786338367152.webp", "9786338367152", "ندبة العمر", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 480, "حسام الحكيم", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يتناول الكتاب بأسلوب علمي مبسط العلاقة الوثيقة بين التغذية والصحة، مسلطًا الضوء على عدد من الأمراض الشائعة المرتبطة بالنمط الغذائي الحديث، مع تقديم نصائح عملية لعلاجها أو الوقاية منها بالتغذية العلاجية.", "/images/products/9786338367169.webp", "9786338367169", "الحكيم باشا دايت بسلاسة", null, 200m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 481, "عهد على محمود", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "استيقظ العالم على كارثة مدوية، كان ( بدر ) نائما و قد ضاقت عليه نفسه كالعادة وفجاة سمع صوت صراخ، ظنها في بادئ الأمر أفكاره الخاصة قد تحولت إلى كوابيس، و لكن عقله بدا يفيق رويدا رويدا حتى استيقظ بالكامل على الصراخ فهب مسرعا من فراشه و ركض خارج حجرته فصادف أمه في الردهة الصغيرة مذعورة فاتسعت عيناه وقال في دهشة:\n_ أماه، ماذا حدث؟!\nلم تستطع الأم الإجابة ولكنه رأى أخته تركض صارخة من حجرتها:\n_ جارتنا في البناية المقابلة ظلت تصرخ في وجه زوجها و قد جنت تماما ثم أشعلت النيران في شقتهما و الزوج داخلها\n** قفز ( بدر) نحو الهاتف وهو يطلب رقم رجال الإطفاء قاىلا في صدمة:\n_ هل جُنّت حقا أم ماذا؟!\nو ما كاد يدلي ببلاغه على الهاتف و ينتهي حتى سمع ثلاثتهم أصواتا مختلطة فأسرعوا نحو نافذة حجرة ( بدر) نفسها حيث مصدر الصوت فهالهم ما راو، جارهم الآخر بالأسفل ، ذاك الرجل كبير السن الوادع الطيب يصفع ابنه الشاب على وجهه و يقسم بأغلظ الأيمان ألا يبيت في بيته ليلة بعد هذا وهو يتهمه بأنه قد سرق أموال عمه التي أودعها عندهم أمانة ثم ظنوا أن لصا قد سرقها و قد حدث كل هذا منذ عامين! تعجب ( بدر) جدا، شجار ينشب بين أب و ابنه من أجل كارثة فعلها الابن منذ عامين؟! ما الذي كشف سر الابن الآن؟! ،ظل في حيرته بينما رن جرس هاتف المنزل فأسرعت ( ميار) إلى الإجابة فأتاها صوت خالتها تبكي منتحبة، لقد طلقها زوجها الذي كان يهيم بها حبا !!\nو عندما نادت الفتاة أمها لتجيب خالتها همهمت الأم في ذهول:\n_ هل جُن الجميع اليوم؟!", "/images/products/9786338367176.webp", "9786338367176", "خلف الأبواب الزرقاء", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 482, "ريهام الجبالى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يتناول العمل قصة حب تنشأ بين اتنين عن طريق وسائل التواصل الاجتماعي، تتطور الأمور بينهما إلي حب.\nلم تتوقف عن هذا الحد تتجاوز ذلك بكثير وتسقط فريسة رجل مزاجي يعاملها حسب حالته المادية قبل النفسية، يلوعها عشقا بالهجر تارة والوصال تارة اخري. تكون فتاة صغيره خبراتها محدودة وهو رجل طاعن العقل والخبرة يستغل ذلك، يسقطها في بئر حبه. ويتمعن في ان يخوض بها ومعها حروبه، تحاول إخفاء الامر عن الجميع. تنساب وتنسجم في القصة معه. فاول اللقاء يجمعهما يكون في المقبرة، كلاهما حزين لموت والدته.\nتتسارع الأحداث وتسقط فريسة لشغفها الشديد به، يصاب في حادثة ويخرج من ازمة لاخري وهي بنفس القوة والعزم معا. تحاول بعدها الابتعاد لا تستطيع فقد سقطت في محيط عشقه غرقاً. يتفقا علي الزواج وامام رفض الجميع يقف الحب مثابراً وينتصر لهما. يوافق الجميع بعد مبارات رفض عنيفة من قبلهم.", "/images/products/9786338367183.webp", "9786338367183", "برائحة الفقد", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 483, "مى إبراهيم القاضي", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ليالي زمان\n\nوحشتني ليالي زمان واللِّمّة،\nوطاقة أمل جوّه القلب\nتنور أي ضلمة.\n\nوحشتني ضِحكة\nمن القلب طالعة\nتداوي أي جرح\nوتمسح كل دمعة.\n\nوحشتني لمّة على صينية،\nولُقمة على القلب هنيّة،\nوبيت يجمع الحبايب\nويسَع منهم مِيّة.\n\nوقعدة في ليالي البرد\nمع كوباية شاي،\nودفا طالع من القلب،\nولا تسأل ليه وإزاي.\n\nيرجع أجمل ذكريات الروح،\nويرجع قلوبنا تاني حيّة.\n\nوحشوني حبايبنا،\nشغلاهم ليه الدنيا؟", "/images/products/9786338367190.webp", "9786338367190", "ليالى زمان", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 484, "هاجر حمدى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يتذكر ذلك اليوم جيدًا عندما عاد من عيادته لم تكن في استقباله كما اعتاد منها، ودلف بحذر يبحث عنها ويناديها دلف لغرفتهما ليجد الرضيع في فراشه نائم وهي وجدها ساكنة تمامًا على مقعد بجانب فراش الصغير وتستند بذراعيها على حائل السرير وتستند بذقنها إلى ذراعيها، لدرجة أنه شك بغفوتها لكن عندما اقترب يميل عليها يقبل رأسها شعر برجف قوي يسري في جسدها فتشنج قبل أن يسرع برفع وجهها له من ذقنها، تفاجئ بدموعها التي تسيل مدرارًا، شعر بقلبه يختلج، منتظرًا تفسير صامت، لكن هي لم تريحه بل وقفت تحتضن خصره وتدفن وجهها في صدره مستكملة بكاءها الحار ذا النشيج الضائعة، وكأنما امرأة خلقت للمعاناة، امرأة قادت حرب ضارية دون درع واحد تحتمي به، وما أوجع قلبه قولها:\n-أنا اعاني من شيء أجهله...", "/images/products/9786338367213.webp", "9786338367213", "اهتداء نفس (عسي أن تهتدى القلوب لساكينها)", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 485, "ضيف الله الجهالين", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تحكي الرواية رحلة شاب بدوي خرج من صحراء الكبرياء إلى طرقات الحياة المليئة بالدخان والتحدي. بين رمال الماضي وزفت الحاضر، يصارع “عزم” نظرة الناس وسخرية القدر، ليصنع من الألم طموحًا ومن الشبهات طريقًا نحو المجد. إنها حكاية عن الصبر، والكرامة، والإصرار حين يقف الحلم في وجه العُرف والمجتمع.", "/images/products/9786338367237.webp", "9786338367237", "عزم بدوى و دكان باص", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 486, "ضيف الله الجهالين", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "رواية تكشف قسوة الواقع حين تتغلّب الواسطة على الطموح، وتحكي صراع شابٍ جنوبي يسعى لوظيفة تحفظ كرامته وسط عالمٍ لا يعترف إلا بالمعارف. قصة واقعية مؤثرة تلامس وجع جيلٍ يطارد أحلامه في وجه الظلم.", "/images/products/9786338367251.webp", "9786338367251", "وظيفة في مهب الواسطة", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 489, "عبدالفتاح صابر", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ونستخلص من هذا أن كعبًا قد يكون مشتركًا في المؤامرة أو على الأقل على علم بخيوطها!\nأو ربما كان مشتركًا في مؤامرة العرب وخاصة القريشيين؛ لأن عمر بن الخطاب قد ضيق عليهم بحزمه ومنع كبار الصحابة وأصحاب النفوذ من الانسلاخ في المدن المفتوحة؛ حتى لا يضطرب وضع العرب وينسون تقاليدهم وعادتهم وأن يبقيهم على بيئة العرب، ولكن أنا أستبعد ذلك لأن عمر نفسه قالها وهو على فراش الموت:\n- ما كانت العرب لتقتلني!\nلتبقى قضية اغتيال الخليفة العادل عمر لغزًا كبيرًا رغم معرفة القاتل الفعلي، ولكن لم نستطع معرفة القاتل الحقيقي الذي خطط وأحبك خيوط المؤامرة", "/images/products/9786338367312.webp", "9786338367312", "الفتنة", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 490, "محمد مندور", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كتاب كيف تنقذ نفسك من الجهل\n\nفي عالم يمتلئ بالمعلومات… ما زال الكثير منا يعيش في متاهة الجهل دون أن يدرك.\n\nليس الجهل مجرد نقص في المعرفة، بل هو قيد خفي يقيّد التفكير، ويشوّه الرؤية، ويجعل الإنسان يعيش حياة أقل بكثير مما يستطيع أن يكونه.\n\nفي كتاب “كيف تنقذ نفسك من الجهل“ يأخذك د. محمد مندور في رحلة فكرية عميقة تكشف لك أخطر أنواع الجهل التي قد تعيشها دون أن تشعر… الجهل الذي يتخفّى خلف العادات، والأفكار الموروثة، واليقين الزائف.\n\nهذا الكتاب ليس مجرد طرح نظري، بل دعوة صادقة للاستيقاظ. دعوة لتعيد النظر في أفكارك، وتكسر القيود التي لم تكن تعلم أنها تحكمك.\n\nستكتشف بين صفحاته:\n\nلماذا يقع كثير من الناس في فخ الجهل رغم التعليم.\nكيف تتسلل الأفكار الخاطئة إلى عقولنا دون مقاومة.\nالطرق العملية لتحرير عقلك وبناء وعي حقيقي يقودك لحياة أكثر فهمًا وقوة.\nكل صفحة في هذا الكتاب قد تكون مفتاحًا يفتح بابًا جديدًا في عقلك… وكل فكرة قد تغيّر الطريقة التي ترى بها العالم… وربما نفسك أيضًا.\n\nإن كنت تبحث عن كتاب يوقظ عقلك، ويهزّ يقينك المريح، ويضعك على طريق الوعي الحقيقي…\n\nفهذا الكتاب لم يُكتب للجميع… بل كُتب لمن يملكون الشجاعة ليعرفوا الحقيقة.\n\nابدأ القراءة… فقد تكون هذه الخطوة الأولى لإنقاذ نفسك من الجهل.", "/images/products/9786338367336.webp", "9786338367336", "كيف تنقذ نفسك من الجهل", null, 400m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 491, "عهد على محمود", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أغمض حمزة عينيه المثقلتين بالحياة التي تنوء الجبال بثقل حملها فرآها....ترتدي ثوبا فضفاضا أبيضا كعروس يوم زفافها...لم تتغير ملامحها الجميلة....يراها الآن علي الهيئة التي تركها يوم أسروه....أمه الرؤوم ولكن ما بعينيها الآن ليست نظرة حنانها المعتادة....إنها نظرة عتاب منكسرة....ركض نحوها بكل قواه...أُوصِدَت من بينهما قضبان سوداء قاسية....نادي بأعلي صوته::: أمي....\nحاولت هي تحريك القضبان لكن القضبان أدمت يديها فأخذت تنظر إليه نظرة انكسار و نهر دموعها يفيض وهي تهمس:: لماذا وضَعتَ هذه القضبان بيننا يا ولدي؟؟", "/images/products/9786338367350.webp", "9786338367350", "صرخة", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 492, "هشام البراوى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في مدينة الطباشير لا يعود الزمن كما كان، ولا المكان كما تظنه.\nبين هند وسماء يتكرر القدر في وجوه متطابقة ومصائر متشابكة عبر القرون.\nرسالة بالدم تُبعث من الماضي، وملك يعود ليُفجر سر الخيانة.\nإلى أرض فلسطين... حيث انعكاس الحقيقة في مرآة الوهم، والنهاية التي كتبت بدايتها.", "/images/products/9786338367367.webp", "9786338367367", "مدينة الطباشير", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 493, "ميسون عبداللطيف", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يتحدث هذا الكتاب عن المرأة المغولية، من حيث مكانتها ودورها في المجتمع، ويسلط الضوء على حياتها الاجتماعية والثقافية والاقتصادية والسياسية، وعلى مسؤولياتها داخل الأسرة والقبيلة، إضافة إلى دورها في بناء المجتمع المغولي والحفاظ على استقراره. كما يهدف الكتاب إلى إبراز ملامح شخصية المرأة المغولية وما تتميز به من قوة وتأثير في مختلف مجالات الحياة.", "/images/products/9786338367374.webp", "9786338367374", "حياة المرأة المغولية في آسيا الوسطى", null, 250m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 494, "محمود مصطفى هلال", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هتلقى الشوق…\nهتلقى الحب…\nهتلقى الحنين…\nهتلقى الوطن… وفلسطين…\n\nهتلقى ضفاير الفتيات… وحواجب النيل…\nورمش القمر طاير على عين الحبيب… 🌙✨\n\nهتعيش ذكريات الشاي على الفحم وقت العصاري… ☕🔥\nوتسمع صوت الناي يبوح في الليالي…\nوتشم ريحة البيوت القديمة… وطَراحة الروح.\n\nهتسمع حكاوي الجد والجدة…\nوتحس طيبة الأب…\nودفا الأخت…\nوكف الأم وهي تلحق دمعتك قبل ما تنزل…\nوقلب الأخ اللي دايمًا يسند… ❤️\n\nهتلقى القهاوي… والناس بتملي كوبايات الشاي…\nوكلام من القلب… بيقعد على الكرسي اللي جمبك.", "/images/products/9786338367381.webp", "9786338367381", "ضفاير الشمس", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 495, "شاكر صبرى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يشملُ هذا الكتابُ كُلَّ ما يَخُصُّ شؤونَ المرأة، وكلَّ ما يشترك بينها وبين الرجل من الحب والعواطف، والزواج من الاختيار حتى الطلاق، وطبيعةِ المرأة وفسيولوجيّتِها، وتطرَّق الكتابُ أيضًا للحديث عن الناحية الفقهية لأمورِ المرأة التي تختلف فيها عن الرجل، وإن تشابها في كل أمور الحياة.\nنريد من خلال هذا الكتاب أن نبعث رسالةً إلى القارئ بأنَّ المرأةَ كائنٌ لطيفٌ جميل، يحتاج إلى رعايةٍ وعناية، يمكن أن يتحوَّل إلى مَلَكٍ أو إلى شيطانٍ، ويمكن أن يُصبح نقمةً على الرجل حين يُسيء معاملتَها أو التصرف معها أو يُهمِلَها حتى يفقدَها.\nالمرأةُ السويّة تستطيع أن تُصلِح الرجل، فالمرأة هي سرُّ الحياة وبدونها لا يمكن أن تستمر، وإصلاحُها وسلامتُها في النهاية هما سلامةُ المجتمع، وهذا ما أردنا أن يشير إليه الكتاب.", "/images/products/9786338367398.webp", "9786338367398", "بين الرجل و المرأة", null, 250m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 502, "قمر سهيل قسطلى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في الظلام يُخبئ الكثير من الأشياء..\nهناك دمعة لا نراها..\nو شوق لا نشعر به..\nو حنين لا يهز أعماقنا..\nو سرٌ لم يُباح به بعد..", "/images/products/9786338367473.webp", "9786338367473", "أربعة فصول من قلبى", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 503, "هبة عبدالعزيز", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذا الكتاب \"سوشيال بيكيا – لايف، ريلز، تريند\" ليس إلا مرآة تلتقط هذه الصور المتكسرة، محاولة لإنقاذ ما يمكن إنقاذه من سوق صاخبة تلتهم كل شيء، إنه تسجيل للوجوه والأصوات قبل أن تتحول إلى أشباح رقمية بلا أثر", "/images/products/9786338367480.webp", "9786338367480", "سوشيال بيكيا لايفات , ريلزات , تيرندات", null, 200m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 505, "فرحه على", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في دهاليزٍ يختلط فيها العلم بالغموض، تتكشف أسرار الخفافيش التي أخفاها التاريخ عن قصد.\nرواية \"جناح وطواط\" عمل يجمع بين الرعب النفسي والخيال العلمي، يكشف كيف يمكن لخللٍ جيني في مملكة الظلام أن يغير مصير الإنسان بأكمله، من خلال رحلة أنيس في مواجهة المجهول، ينكشف صراعٌ بين العقل والإيمان، بين ما نعرفه وما نخاف اكتشافه.\nلغة الرواية آسرة، مشحونة بالتفاصيل والرموز العلمية، لتقدم رؤية جديدة لعلاقة الإنسان بالمخلوقات التي تحيط به \"حين يفتح جناح الوطواط، يبدأ الضوء في طرح أسئلته الموجعة\"", "/images/products/9786338367510.webp", "9786338367510", "جناح واطواط", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 508, "عدنان مشهى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كي لا تبكي ليس وعدًا بالخلاص بقدر ما هو محاولة للتخفف؛ هو دعوة لأن نترك الدمع يجري حين يعجز الصدر عن الاحتمال، ولأن ندرك أن الحزن ليس عيبًا، بل حالة إنسانية تُعيدنا إلى جوهر ضعفنا الجميل. كل قصيدة في هذا الديوان تحمل عزاءً خفيًا، وتُمسك بيد قارئها كي تهمس له: “لستَ وحدك في حزنك، هنا من شاركك الوجع، ونسج لك من دموعه حروفًا تواسيك.”\n\nستجد بين هذه الصفحات لوحات من الانكسار، واعترافات صريحة، وصرخات مكبوتة، ولكنك ستجد أيضًا بصيص نورٍ يتسلل بخجل، وكأن الشاعر يريد أن يقول: “حتى في قاع الحزن، هناك ما يستحق الحياة.”", "/images/products/9786338367558.webp", "9786338367558", "كى لا تبكى", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 509, "أسماء أبو المجد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذا الكتاب استراحة للتفكر والتأمل، رحلة مع “ميس عالية” – معلمة بخبرة تزيد عن عشر سنوات، وقفت في الصفوف مرات لا تُحصى، عاشت لحظات الفرح والإرهاق، وواجهت تحديات التدريس اليومية التي تشبه موجات البحر صعودًا وهبوطًا، صخبًا وهدوءًا.\nفي هذه الصفحات، لن تجدي مجرد حكايات تُقرأ… بل ستجدين مساحات لتدوين أفكارك، وكتابة مشاعرك، والتوقف للحظة مع نفسك.", "/images/products/9786338367565.webp", "9786338367565", "ميس عالية (استراحة للتفكير والتأمل فى مهنة التعليم)", null, 200m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 510, "سارة سامى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "اتخذت الفرحة طريقها إلي قلبه و وجهه، محدثاً نفسها بسعادة بالغة…\n\nأكيد ياسمينتي هتفرح بيه أوي، شكرا يا رب، اللهم لك الحمد.\n\nأخذ هذا الشيء الذي يراه الكثيرون شيئا هينا، صغيرا، بسيطا، لا يبالون أنه أمر شاق علي غيرهم، كما أنه كبير جدا لهم..", "/images/products/9786338367572.webp", "9786338367572", "برائحة الياسمين", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 511, "نهى السعدى", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في أعماق الذاكرة، هناك شيء ما يشبه الغرف المظلمة ، نتجنبها ولا نقترب منها..\n\nهي ليست منسية، ولكننا نخاف من تذكرها.\n\nلقد عاش الكثير من الناس طفولة لم تكن سهلة ، ولا دافئة ،\n\nبمعنى أنه (خسر طفولته)..", "/images/products/9786338367619.webp", "9786338367619", "من الصمت إلى الشفاء", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 512, "ولاء مصطفى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الحياة أشبه برقعة شطرنج\nيجب عليك أن تحافظ على الملك خاصتك حتى تنتصر في تلك المعركة.\nعليك أن تتعلم كيف تحول كل القطع التي أمامك لوسائل مساعدة لنجاتك حتى قطع العدو، لا تعتقد أن في تلك الحياة مبادئ وأنك تستطيع النجاة دون أن تؤذي أحد، فالحياة تضعك باختبارات إما تنتصر أو تُهزم، ولك مطلق الحرية.", "/images/products/9786338367626.webp", "9786338367626", "كاميرا الأحداث", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 513, "إبراهيم عبدالرحمن", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "قل خيرًا أو اصمت.\nيا أصدقائي! من الأشياء الفاضلة أن يكون المرء قليل الكلام فمن كثر كلامه كثر خطأه، وفضول الكلام لا يأتي بخير.\nوإذا دعت الحاجة المرء إلى الكلام فليقل خيرًا أو ليصمت وهو علامة من علامات الإيمان فعن أبي هريرة ـــ رضي الله عنه ــــ أن النبي صلى الله عليه وسلم قال: \" ... ومن كان يؤمن بالله واليوم الآخر فليقل خيرًا أو ليصمُت\" متفقٌ عليه.\nوالمرء قليل الكلام يهابه الناس أو الصامت حتى يتحدث والعرب تقول:\nتكلم حتى أراك أي: حتى أعرفك. فالمرء مخبوءٌ، تحت لسانه.", "/images/products/9786338367633.webp", "9786338367633", "إليك يا صديقى", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 519, "رشا طلب", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الرواية …مهداة إلي العائدون من الفقد، من تعلقوا بظلال الماضي و سحبتهم خيوطه لعالم من الخيال فذابوا بين ظلاله و صعب عليهم الخروج من غيابات الأوهام و الذكريات.\nعن الكاتبة.. رشا فاروق طلب مدرسة ماث و خريجة كلية العلوم قسم الفيزياء و الفلك.. أحببت الكتابة منذ طفولتي و لي مشاركات في كثير من المدونات و روايتي الظل هي أول رواية أطلق سراحها لتخرج إلي النور.", "/images/products/9786338367701.webp", "9786338367701", "الظل", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 521, "أحمد الرفاعى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "” الشمسُ تلوحُ في الأفقِ، تُرسلُ أشعتَها الذهبيةَ على مياهِ الترعة، لتكشفَ عن مشهدٍ تقشعرُّ لهُ الأبدانُ: جثثُ خمسةِ شبابٍ طافيةٌ، بوجوهٍ خاليةٍ من الحياةِ. النساءُ يصرخنَ ويذررنَ الترابَ، والرجالُ يراقبونَ بصمتٍ موجعٍ، وقلوبُهم تعتصرُها الحسرةُ على ضياعِ فلذاتِ أكبادِهم. وسطَ هذا الألمِ، يمدُّ بعضُ الرجالِ أيديهم لينتشلوا الأجسادَ الباردةَ من الماءِ “", "/images/products/9786338367749.webp", "9786338367749", "الملعونين", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 522, "عبدالنبى خطاب", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "همس الكلام وشوشة\nح أقوله يمكن يشفعلك\nنصيحة مني قلتها\nقبل الزمان ما يوجعك\nهمس الكلام قصور سلام\nصوت ضميرها يسمعك\n\"ارجع وتوب من الذنوب\"\nصوت الأذان ح يرجعك", "/images/products/9786338367756.webp", "9786338367756", "همس الكلام", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 526, "عبدالحميد إبراهيم", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ليست مجرد حكاية تُروى، بل صرخة دفينة تسكن صدورًا كثيرة.\nتتقاطع فيها ملامح القهر مع بقايا الأمل،\nوتتوارى الأحلام خلف جدران الصمت الطويل.\nلكن في قلب الظلام تنبت دومًا رغبة في التحليق، رغبة في كسر القيود التي وُلدنا بين أسلاكها.\nربما تجد هنا نفسك، أو ظلّك، أو ما لم تجرؤ أن تبوح به يومًا.", "/images/products/9786338367817.webp", "9786338367817", "أجنحة بين القيود", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 536, "ميليا عبدالكريم محسن", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في عالمٍ تحكمه الأسوار، يولد نورٌ صغير يرفض الخضوع.\nبداية رحلة بين الخوف والشجاعة، حيث يكون السؤال الأول:\nهل يكفي النور ليبدأ التغيير؟\n\nللكتاب جزء ثانٍ: الجزء الثاني.", "/images/products/9786338367954.webp", "9786338367954", "النور الذى هدم السور", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 537, "ميليا عبدالكريم محسن", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "رسالةٌ مجهولة، وزجاجةٌ قذفتها الأمواج، وفتاةٌ تقف كل يوم عند الأفق، لا تعلم أن قلبًا يراقبها بصمت.\nحكاية حبّ تبدأ من بعيد، وتنمو في الانتظار، حيث يصبح الصمت لغةً، والأفق وعدًا.", "/images/products/9786338367961.webp", "9786338367961", "حائزة فى الافق", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 538, "محمد مندور", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هل شعرت يومًا أنك تعيش حياتك… لكنك لا تعرف نفسك حقًا؟\nأن هناك شيئًا في داخلك يحاول أن يتكلم، لكن ضجيج العالم يمنعه؟\n\n“رحلة إلى ذاتك – متاهات القوة والضعف“ ليس كتابًا عاديًا عن تطوير الذات، ولا مجموعة نصائح محفوظة يمكن أن تقرأها ثم تنساها. إنه مرآة صادقة ستضعك وجهًا لوجه مع نفسك… مع قوتك التي لم تكتشفها بعد، ومع ضعفك الذي حاولت الهروب منه طويلًا.", "/images/products/9786338367985.webp", "9786338367985", "رحلة إلى ذاتك متاهات القوة والضعف", null, 450m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 539, "محمد مندور", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ليست كل الروايات تُكتب… بعضها يُصنع بمهارة.\n\nلماذا تنجح بعض الروايات في أسر القارئ من الصفحة الأولى… بينما تتعثر أخرى رغم الفكرة الجيدة؟\n\nما السر الذي يجعل القارئ يسهر الليل ليكمل رواية؟\nوكيف يخلق الكاتب شخصيات تبدو حقيقية كأنها تعيش بيننا؟\n\nفي هذا الكتاب ستكتشف الأسرار الخفية لصناعة الرواية… الأدوات التي يستخدمها كبار الروائيين دون أن يتحدثوا عنها كثيرًا.", "/images/products/9786338367992.webp", "9786338367992", "الدليل السري لكتابه الرواية (متداول جملة فى اخر همسة)", null, 300m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 540, "هدير مجدى العجمى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "“حين تمتزج القهوة بالنبيذ… يولد جيل لا يهاب الخيانة.”", "/images/products/9786338387020.webp", "9786338387020", "قهوة بطعم النبيذ", null, 250m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 541, "على لفته سعيد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تسبّبَ الخدرُ والنعاسُ وحركةُ السيّارة وصوتُ عجلاتِها بنومِ الجميعِ. كانَ ضوءُ الفجرِ الرمادي يعلنُ تمدّدَهُ بشكلٍ طبيعي، وتلّوحُ زرقةُ الصباحِ قبلَ أنْ يخرجَ قرصُ الشمسِ الذي سيكونُ أمامَ وجهِ الجالسينِ على جهةِ اليمينِ. لا شيءَ يمكنُ أنْ يحرّكَ الجفونَ المستسلمةَ للذّةِ النعاسِ سوى تعبُ الرقابِ من إيجادِ مكانٍ مريحٍ على مساندِ المقاعدِ، لتتشعّبَ الحركاتُ في البدءِ ثم تلوذُ بالنومِ…كلُّ شيءٍ هادئٌ في بطنِ السيّارةِ التي تتلذّذُ بهواءِ تشرينَ الداخلِ من نوافذَ مفتوحةٍ قليلًا، وكأنَّها تعبّئُ ما ينقصُ العمرَ من هواءٍ منعشٍ لم تحفلْ به الأجسادُ من قبلُ.", "/images/products/9786338387037.webp", "9786338387037", "ستاريكس", null, 200m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 542, "على لفته سعيد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لقد اعتبر المؤلف طريقة إنتاج النص لعبة، ولكن هل يحمل الملفوظ دلالته المألوفة والمعتادة فقط؟\nإن اللعب بما هو تحرّر من الصرامة والجدية والإلزام إلّا أنه خاضع لقوانين ضابطة، قد يبدو المصطلح غريبًا لأوّل وهلة، لأنه يؤوّل إلى الاستصغار وينحرف نحو دلالة الإهمال والانتقاص ويدل على مالا يلزم، إذ لا جدوى منه ولا فائدة ترتجى منه، لكنه يفيض بالإتّقان ويعوّل على الترجيح وحسن التدبير والدربة حتى يسير إلى ما يفترض به، وهذه القصدية هي التي تأسّست عليها إشكالية الكتاب، لذلك وأنا أقرأ ما ورد فيه، ومع كلّ جزئية تمرّ بي، يزيد اقتناعي بأن الأستاذ علي نفسه يمارس هذه اللعبة على مستوى النقد أيضا، أو ما يمكن اعتباره لعبة تأويلية تتقصّى المضمر، إذ يحاول أن يقود التفكير النقدي ناحيته ويقنعنا بأن الدهشة والخرق هما ما يضمنان إتّقان اللعبة ،وأن الناقد المتمرّس هو الذي يبرز هذه القدرة الإبداعية بعيدا عن الصبغة التبجيلية، وبعيدا كذلك عن الرؤية التي تجد في القراءة فعل محاكمة تتصيد الأخطاء فقط .", "/images/products/9786338387044.webp", "9786338387044", "فهم اللعبة الإنتاجية", null, 200m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 545, "ماجدة مرسي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تبدأ أحداث الرواية بمشهد لأسطورة تتحدث عن تاجر خسر الكثير من أمواله فقرر اصطحاب ابنه الوحيد والبحث عن كنز أخبره عنه أجداده، مكان الكنز هو صخرة عين التنين الموجودة في صحراء سيناء بعد بحث شاق يكتشف الأب أنه حرر الكنز وحرر معه روح سعدة بنت جرهم ساحرة عربية قديمة دفنت في هذا وقد سحرت سبعة من خيرة شباب قبيلة جرهم و جولتهم وحوشا لا يعيشون مع البشر فدعا عليها أحد الصالحين فماتت ودفنت في ذلك الكهف وحولها كنوز كثيرة وذهب لا يعد ولا يحصى.", "/images/products/9786338387075.webp", "9786338387075", "جبل سيما", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 546, "أحمد المؤذن", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذا الليل ليس قصيدة ولكنه ربما يكون مواعيدًا للهوى، يمكن صرف متعتها من مصرف الخيانة الصامتة عندما تسأم المرأة زوجها وتقرر استبداله.. القصص التي تجدها من خلف الغلاف مليئة بالثقوب ومغلفة بغموض الليل.\n\nكل ثقب يُعلن عن نفسه بصراحة صادمة تشتعل في اشتهاء الخطيئة التي يوقد نيرانها إبليس، يتخطى محطات انتصاره ويضحك على ضحاياه. لتعذرني أيها القارئ فيما لو وجدت لنفسك هنا محطة توقفت في ليلها ذات يوم وحفرت لنفسك ثقبًا (…………)، فما أنا هنا بوارد التماس العزاء لحضرتك، ولا أنوي أذيّتك، لكن ورطتك في النهاية تخصك، ووقتئذٍ أقلب الصفحة فقط وأهرب من الثقب أو إليه وتتقبل مصيرك كيفما كان. لا تقلق، أترك عنك ثرثرة المقدمة وتعال معي نمشي بهدوء، فالطريق وعرة قليلًا بهذا الليل، وستجده يستبدل في كل مرة جلده مع كل قصة، خُذ الحذر!", "/images/products/9786338387082.webp", "9786338387082", "في ثقب الليل", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 547, "أحمد المؤذن", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يمكن قراءة مجموعة “رجل للبيع” للكاتب البحريني أحمد المؤذن عبر تفكيك الدلالة السيميائية للعنوان؛ مفتاح النص. فالمفردة الأولى “رجل” من دون إضافتها لما قبلها، اسم نكرة، وهي في الوقت نفسه قوية الدلالة، ولها وقعها الخاص والمقدس في العقلية الشرقية، وعند إضافة الكلمة الثانية لها “للبيع” تتحول هذه النكرة إلى معرفة، وتنجلي عنها قدسيتها إذ “الرجل” موضوعيًا، يصبح سلعة قابلة للتداول.\nإنها لعبة المتناقضات المشغولة بها جلّ قصص المجموعة، والتي تجسد نوعًا من السخرية التي تؤكد وعي الذات تجاه نفسها في لحظات ضعفها وانكسارها وفقدانها مكمن قوتها وبحثها المحموم في ثنايا عالم مختل ومتقلّب، عن فسحة تنفذ منها لتسترد قوتها. والمؤذن هنا يستثمر بوعي هذا الأسلوب ليقدم رؤية مغايـرة للعالم متأتية من نقد الذات الفردية وبالتالي نقد المجتمع المتأسس على مجاميع من الذوات؛ محاكمته وكشف زيفه وتعرية المستور فيه.", "/images/products/9786338387099.webp", "9786338387099", "رجل للبيع", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 548, "ندي إبراهيم", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"قصة ممتعة وهادفة تأخذ الأطفال في رحلة شيّقة مليئة بالمواقف البسيطة والمعاني العميقة، حيث يتعلّمون من خلالها قيَمًا جميلة مثل الصدق، والتعاون، وتحمل المسؤولية. بأسلوب سهل ومحبّب، تساعد القصة الصغار على تنمية خيالهم وتعزيز سلوكياتهم الإيجابية بطريقة ممتعة وشيّقة.\"", "/images/products/9786338387105.webp", "9786338387105", "الفيل جميل ورد الجميل", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 549, "السيد الشايب", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ذا كتابي جمعت فيه بعضًا من هموم أمتي وقضاياها المهمة، وتدارست أسبابها وسعيت وراء مقاصدها، وتدبَّرت حلولها ما شاء الله لي القدرة على ذلك، فكتبت عن دينها وثقافتها وآدابها وتاريخها وموروثها، فتباكيت وغضبت وأشفقت، وهو مقالات تتناول أحوال الأمة الإسلامية من نواحيها الدينية والتاريخية والأدبية والفكرية، تناولًا يبيّن الحرب الاستعمارية على هذه الأمة، الحرب التي لا تتخذ جبهة بعينها، فإن قصفت القلم فذا مغنم، وإن ضربت الجباه فذاك الهدف، وكل نتيجة تُوقف هذه الأمة عن غايتها هي مغنم لهم.", "/images/products/9786338387129.webp", "9786338387129", "مصارعة الاخلاق", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 550, "حنان الدومى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "حِمْلَ صَدْرِي\nوَإِشْرَاقِي،\n\nفُكَّ قَيْدِي\nوَوِثَاقِي..\n\nإِنِّي وَالْجُنُونُ\nفِي سِبَاقٍ\nوَالْحِلْمُ وَالْعَقْلُ\nفِي طِبَاقٍ..\n\nنَجْرِي\nإِلَى لَا مُسْتَقَرٍ\nكَالْبُرَاقِ..\n\nحِمْلَ صَدْرِي\nوَإِشْرَاقِي،\n\nدَعْكَ مِنِّي\nوَمِنْ إِغْرَاقِي..\n\nفَلَا أَنتَ أَرْضَ\nمَقْدِسٍ وَلَا عِرَاقٍ..\n\nلَكِنَّ مَوْتِي فِيكَ..\nشَهَادةٌ،\nوَتَحَرُّرِي مِنْكَ..\nفِيهِ انعِتَاقِي..\nالشاعرة حنان الدومي", "/images/products/9786338387136.webp", "9786338387136", "بأي بلسم تشفى أعماقي", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 552, "إلهام عبدالمعز", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "٠ ليس كتابًا عابرًا سيمضي عليك، أو ينساب من بين يداك دون أن يُخلِب عيناك ، وتلتهمه حواسك ، بل سيرنو من روحك حتى يأسِر وجدانك .\n\n٠إنه يغوص في أعماق الروح وكينونة الذات المُزينة بالفطرة الإلهية .\n\n٠ مجموعة من الرحلات التي قد تبدو لك واقع، وقد يُبصِرها عقلك خيال .\nلكنه حتمًا سيجد المرسى ويبلُغ الميناء .\n\n٠ أنا معك هنا حتى نربط بين الواقع والخيال، وأُريك أن الخيال ليس خارج حدود الفطرة. بل الواقع والخيال بينهما رابط وثيق أنهما معًا تحت وطأة الإله .\n\n٠ لنرى كيف للفطرة الإلهية أن تُبحِر بك في عوالم الكون، وتصل بك إلى شط النجاة . بشرط أن تكُون مُحكًمة بالإيمان بخالق الأكوان، وتُردِف الأصل وما أنزل الرحمن .\n\n٠ إنها الفطرة صانعة المعجزات، خالقة الإبداع، مُلهِمة الأنام .\n\n٠ إنها الفطرة الربانية من الله ذي السلطان للورى عبيده في سائر الأزمان .", "/images/products/9786338387174.webp", "9786338387174", "سرداب الفطرة الإلهية", null, 140m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 554, "مروة ابراهيم محمد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "اقتباس ظلَّ يراقب شيئا ما داخل المرآة حتى ظهر انعكاس كائنٍ طويل القامة بشع المنظر، له قرنان ملونان باللون الأحمر، جسده أسود اللون، ولديه أظافر طويلة جدًا مقززة للغاية.\nفجأة اختفى ذلك الكائن من انعكاس المرآة، ليتحول زجاجها إلى اللون الأسود الفحمي، ثم صدر صوتٌ كفحيح الأفاعي يبدو أنه قادمٌ من الجحيم.", "/images/products/9786338387198.webp", "9786338387198", "لابرادوريت (أرض الحقيقة)", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 555, "محمد ابراهيم حجاج", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ربما صدمة تجعل من الإنسان شخصا آخر\nوربما موقف يجعله يتناسى دوره الحقيقي في الحياة ليتحول 180 درجة\nربما هي، نصف الحقيقة فقط\nمرآة وقد عكست الحقائق أصبحت الأدوار مغيبة\nوما زال للحديث بقية", "/images/products/9786338387211.webp", "9786338387211", "الشقة 69", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 556, "عدى عبدالفتاح", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "العنود كاتبة لا يهمها سوى الورق والقلم والصمت, عاشت حياتها في أوائل التسعينات بهدوء ظاهري، تقضي نهارها في وظيفة عادية، وقليلًا ما تسألت إن كان هناك من يسمع صمتها الداخلي. في إحدى الليالي، تلقت رسالة بلا اسم مكتوبة فيها:\n\n“لقد شاهدناكِ… لا تنظري في المرآة”", "/images/products/9786338387228.webp", "9786338387228", "العنود (الوجه الذى لا ينعكس)", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 557, "محمد يحيى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "اليوم رقم خمس و أربعون منذ بدء الرحلة , بعد تفجيرات النووي التي ملأت جوانب كوكب الأرض واختفت الحياة –وصلت من مجرة مجاورة لمجرة درب التبانة بعد رصد انفجارات نووية علي الأرض , الشمس لا تصل أشعتها الي ظهر الكوكب ( كوكب معتم ) , الغبار ما زال يمتلئ ببعض المواد المشعة ,. لا رصد لأي حياة حتى الآن.", "/images/products/9786338387235.webp", "9786338387235", "اتصال واحد", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 558, "إسراء كمال", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في زمنٍ اهتزّت فيه عروش الممالك، وخرج من أعماق العدم نسلٌ من الملوك… خُلقوا من الظلام.\nسقطت الممالك أمام قوتهم، ثم سقطوا هم أمام قدرٍ كتبته اللعنة. لكن الأسطورة لم تنتهِ… فدماء ملوك الظلام ما زالت تغلي.\nحين تختلط النبوءة بالقدر، يصبح الولاء خيانة، والحبّ سلاحاً مميتاً.\nتتشابك الأرواح القديمة بالجديدة، وتستيقظ أسرار دفنتها الحروب.\nحيث لا ينجو إلا من يُجيد اللعب بالنار… وفي الظلام.", "/images/products/9786338387242.webp", "9786338387242", "ملوك الظلام", null, 160m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 559, "منى منصور السيد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كانت تلك الليلة ككل الليالي المنصرمة على سكان ذلك المنزل المتهالك ذي الطابقين في الحارة الضيقة، يلاصقه عدد من البيوت القديمة، لا يغيب عن ساكن فيها ما يدور حوله في الغرف المجاورة، ناهيك عن تحيات الصباح والمساء المتبادلة بينهم عبر النوافذ، كأنهم على وشك المصافحة يوجد بعض الحوانيت، منها دكان صغير لبائع الخردوات عم جابر، له باب خشبي متهالك ذو درفتين، رجل طاعن في السن، أتت الشيخوخة على كل مفاصله، له جسد واهن، في الساعات المبكرة من الصباح يعتريه رجفة من الألم الممض، أصوات طقطقة أسفل ظهره، حتى ليسمعها من يقترب منه و كأن عموده الفقري على وشك الانهيار، ستتناثر عظامه على الأرض.", "/images/products/9786338387266.webp", "9786338387266", "خارج صندوق الأحلام", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 560, "غدى عبدالفتاح", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ذلك العالم لا يخضع لقوانين الطبيعة، ولا يحكمه منطق العقل، تسكنه كيانات لا تعرف الرحمة، ولا تفهم البشر, إلا كما نفهم نحن ظلالنا, نراها، لكنها لا تملك ملامح.\nمنذ قرون، ظل هذا العالم مفصول بستار خفي، لا يراه إلا من ضلّ الطريق أو كُشف له الحجاب, لكن ما لا يعرفه الكثيرون, أن هناك من يتعمد فتح هذه الستائر، ومن يبيع روحه إلى الجانب الآخر.\nلم أكن أؤمن بشيء, حتى بدأت أسمع الأصوات ليلاً، وأشعر بأنفاسٍ لا يراها أحد، وأرى أعينًا تتوهج في الظلام. منذ تلك الليلة، حين استدعيت شيئًا ظننته لن يجيب, لكنه جاء.\nيجب أنك تقرأ هذه الكلمات، لأنك ستعرف قريبًا أن بعض الأبواب لا يجب طرقها، وبعض العوالم, لا يجب أن تُزار أبدًا.\nهذه ليست حكايات من وحي خيال، بل اعترافات متأخرة، ووثائق نجت من حريق الحقيقة, اقرأها إن كنت تملك الجرأة، لكن تذكّر, أن بعض الطرق لا عودة منها، وبعض الأسماء حين تُنطق تُوقظ ما لا ينبغي إيقاظه", "/images/products/9786338387273.webp", "9786338387273", "باب اللعنات", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 561, "محمد يحيى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أود أن أرحب بجميع المتأهلين إلي تلك المرحلة , لقد قدمتم للجنة المسابقة أسبابا كافية ومقنعة للتقدم خطوة أخري في طريق الثلاث المختارون و طبقا لتعليمات لجنة المسابقة فهناك ثلاث إختبارات يسعدني أن أخبركم بأنها ستكون صعبة للغاية وهي تختبر صبركم وقوتكم وشجاعتكم", "/images/products/9786338387280.webp", "9786338387280", "إقتلونا رجاء", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 562, "رحمة أحمد السيد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في مكانٍ ما بين العقل والجنون، بين اليقظة والحلم، يتسلّل صوتٌ خافتٌ كأنما يأتي من أعماق الجحيم نفسه… لا يحمل لعنات، بل أناشيد، مزامير تُتلى على أرواحٍ ضلّت طريقها.\n\nكل قصة هنا ليست حكاية رعب تقليدية، بل مرآة سوداء تعكس وجوهنا حين ننظر لأنفسنا دون أقنعة.\n\nفي “مزامير الجحيم” لا وجود لوحوشٍ تُطاردنا من الخارج، بل لأفكارٍ تنهشنا من الداخل، لمخاوف نغذّيها نحن بأيدينا حتى تستيقظ وتبتلعنا.", "/images/products/9786338387297.webp", "9786338387297", "مزامير الجحيم", null, 140m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 563, "أسماء محمد عبدالسلام", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هل جرّبت أن ترى وفاة أشخاص لا تعرفهم… ليست رؤية عادية وليست رؤية سابقة… الرؤية هنا رؤية من نوع آخر… رؤية مستقبلية، تستطيع رؤية وفاة الأشخاص فقط من النظر إلى أعينهم، ولن تستطيع أن تفعل شيء لهم، تراهم يموتون عن بعد… احترس…. إذا لديك قلب ضعيف، فلا تأخذ هذه الرواية… فأنت…. مع الأيدو..!", "/images/products/9786338387303.webp", "9786338387303", "الأيدو", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 564, "سوزان الفطيرى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "«من دفتر العمر» هو كتاب شعري يقدّم للقارئ رحلة إنسانية صادقة وممتدة عبر محطات الحياة المختلفة، كأنه دفترٌ مفتوح يسجّل لحظات الفرح والحزن، الانتصارات والانكسارات، الأحلام المؤجلة والذكريات التي لا تُنسى. يأتي الديوان بالعامية المصرية ليكون قريبًا من الناس، قادراً على لمس مشاعرهم دون حواجز لغوية أو تعقيدات. فالكاتب هنا لا يكتب شعراً فقط، بل يكتب نبض القلب وهو يتقلب بين فصول العمر.", "/images/products/9786338387310.webp", "9786338387310", "من دفتر العمر", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 565, "رحمة أحمد، حسين العربى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تحت بيتٍ ملعون يرقد مجلد فرعوني غامض… كل من اقترب منه، انفتح له باب إلى ما لا يُرى.\n\nكوابيس متشابكة تكشف وجوه الماضي والحاضر والمستقبل، تقود إلى الحقيقة — أو إلى اللعنة ذاتها.\n\nرواية تُعيد تعريف الرعب، حيث لا يميّز القارئ بين ما يراه نائمًا… وما يعيشه يقظًا.", "/images/products/9786338387327.webp", "9786338387327", "لعنة المجلد الأسود", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 566, "علاء سرحان", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدور أحداث الرواية في مدينة الإسكندرية مطلع القرن العشرين، في زمنٍ يقف على تخوم التحوّل بين التقاليد الموروثة وبدايات الحداثة، حيث تختلط طموحات الأفراد بمصالح العائلات الكبرى، وتتقاطع الأحلام الرومانسية مع حسابات المال والسلطة.", "/images/products/9786338387334.webp", "9786338387334", "عتمة الظلال حين تنطفئ الظلال", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 567, "علاء سرحان", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تبدأ الحكاية كأنها مجرد قصة عائلة، لكن سرعان ما تنكشف طبقات أعمق تجعل القارئ يكتشف أن العائلة ليست سوى خيط صغير في مسرح كونيّ دمويّ لا ينتهي.", "/images/products/9786338387341.webp", "9786338387341", "ذبيحة الظلال حين تتمدد الظلال", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 568, "هالة عبدالله", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "“أساسيات المحاسبة المالية” هو دليلك العملي لفهم المحاسبة من البداية وحتى إعداد القوائم المالية بثقة. يقدم الكتاب محتوى متكاملاً لكل من يسعى إلى بناء أساس راسخ ومنهجي في المحاسبة، بدءًا من مبادئها الأولى ووصولًا إلى التطبيقات العملية المتقدمة.\n\nيعتمد الكتاب على شرح تفصيلي مبسط مدعّم بالأمثلة والتمارين، ليكون مرجعًا موثوقًا للطلاب، وحديثي التخرج، والمحاسبين المبتدئين، وكذلك المهنيين الراغبين في تطوير معرفتهم. ويتميز بأسلوب تطبيقي يغطّي مختلف المعالجات المحاسبية، إلى جانب تبسيط أهم النسب والمؤشرات المالية المستخدمة في التحليل.", "/images/products/9786338387358.webp", "9786338387358", "أساسيات المحاسبة المالية", null, 300m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 569, "حسين العربى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كل شيء يبدأ بالصمت…\n\nثم يتحول الصمت إلى صوت،\n\nوالصوت إلى صراعٍ ينهش الداخل حتى لا يبقى سوى الرماد. في هذا العالم، لا فرق بين الصراخ والصمت،\n\nفكلاهما وجهٌ لذات العذاب.\n\nالوجوه تتشقق، الحقيقة تنزف،\n\nوالعقل ينسج خيوطه حول الفقد كبيتٍ للعنكبوت.\n\nهنا، يُمحى الخط الفاصل بين الحلم والجحيم،\n\nوتنقلب المرايا على أصحابها.\n\nلا تبحث عن الضوء… فكل خطوةٍ نحوه\n\nقد تكون بداية للاحتراق.لا قوانين هنا،\n\nولا منطق يحكم ما هو آتٍ، كل شيء يخرج عن السيطرة،\n\nخارج الإدراك ، خارج الحقيقة…\n\nخارج حدود الصمت", "/images/products/9786338387365.webp", "9786338387365", "خارج حدود الصمت", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 570, "علاء سرحان", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "رواية حين تستيقظ الظلال هي الجزء الثاني المكمل لرواية حين تنطفئ الظلال، وهي عمل من تقاليد الرعب النفسي والتشويق الغامض، ليدمجها مع حبكة عائلية مأساوية تحوّل البيت القديم وقصر العائلة إلى مسرح للدم، اللعنات، والأسرار المدفونة.", "/images/products/9786338387372.webp", "9786338387372", "دم الظلال حين تستيقظ الظلال", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 571, "عبدالعاطى إسماعيل", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "«ظلال الروح»\nحكايةُ رجلٍ ظنّ أن الحبَّ وحده يكفي،\nوامرأةٍ خافت أن تُسلّم قلبها قبل أن تطمئن،\nوحكايةُ طريقٍ بين القاهرة وقِنا،\nبين الانفتاح والجذور،\nبين الرغبة في الطيران\nوالخوف من كسر الجناحين.\nهي ليست قصة حبٍ فقط،\nبل شهادةٌ على أن بعض العلاقات\nلا تنهار بسبب الكره،\nبل بسبب الخوف…\nوحين يخاف القلب،\nتظهر ظلالُ الروح.", "/images/products/9786338387396.webp", "9786338387396", "ظلال الروح", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 572, "دنيا صابر", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مجموعة شباب وبنات من عائلة واحده ينتقلون لبلدة أخرى غربيه لأستكمال دراستهم ودخول الجامعه حيث أنه تم قبولهم بمنحه مجاني، و بنصف العالم الدراسي تقترح واحده منهم أن يذهبوا لرحله استكشافيه لبلده قريبه منهم والطريقه الوحيده للذهاب إليها هو القطار ليقع بيهم الحال هم ومن معهم بالقطار المرور عبر بوابه خفيه تنقلهم من زمنهم لزمن أخر ومن هنا تبدأ الصعاب وأستكشاف المكان لتقع الكارثه عليهم بعدما علموا أنهم عادوا بالزمن للعصر الفكتوري وكلما حاولوا العوده تذهب محاولاتهم سدى فيقرروا التأقلم على الوضع والتكيف.", "/images/products/9786338387402.webp", "9786338387402", "وعد لندن", null, 250m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 573, "أحمد مرجان", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ببساطة ستجد في العمل البسيط هذا ما يلي:\n1. مائة كتاب، كانوا رفاقي في رحلتي، ولو أن جهلي الشديد لن ينتهي.\nربما يقودك أحدهم إلي فكرة، أو يُرشدك إلي رؤية جديدة.\n2. مائة مقطوعة موسيقية، يَكفي أن أُخبرَك أنها كانت إحدي وسائِلي لِبلوغِ ما لم أكن أتَصَوّر وجوده، ولكَ أن تَتَجاوزها إن لم تكن تروق لك.\n3. مائة رسالة قصيرة. لأكونَ صادقًا معك، هي رسائل كنت أتمني لو أرسلها لي أحد، فَكتبتُها بِنفسي، لِنفسي، ووددت مشاركتها معك، ربما نلتقي من خلالها فيها .\n4. ووضعت لك ثلاثمائة سؤال. الأسئلة هي المعبر بين ما نعرف وما نجهل، ربما لا أعرف معظم الإجابات، لكن مجرد وجود السؤال اللائق، بمثابة فرصة للكشف عن الإجابة في الوقت المناسب .( الإجابات الصادقة قد تُعيدُ صِياغةَ حياتِك.", "/images/products/9786338387426.webp", "9786338387426", "نشوة الأعالى", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 574, "سمر سعيد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "خرج من باطن البحر صوت عميق ينادي باسم حمزة!، التفت حمزة حوله في حيرة يبحث عن مصدر الصوت ظن أنها دعابة سخيفة من أحد أصدقائه لكنه لم يجد أحد سواه هو ونور، عاد الصوت مناديا مرة أخرى بصوت أكثر عمقا جعل كل من حمزة ونور ينتفضان\n– أن أردت معرفة الحقيقة اقرأ هذه الرسالة!", "/images/products/9786338387433.webp", "9786338387433", "ساردار", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 575, "أحمد هيبة", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "حكايات من سيارة إسعاف، الجزء الثاني (و من أحياها، بطولات، وإنسانيات)\nمجموعة من القصص الحقيقية (29 قصة) التي قابلها العديد من زملائي أثناء عملهم بالإسعاف المصري (البطولات).. و قصص أخري كنت شاهد عيان علي تفاصيلها (الإنسانيات).. في الجزء الأخير أروي قصتين لشخصين قريبين مني..", "/images/products/9786338387440.webp", "9786338387440", "ومن أحياها (بطولات و انسانيات )", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 576, "عبدالعليم مبارك", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "رواية «جيلا» للكاتب عبدالعليم مبارك، والتى تسلط الضوء على قضايا إنسانية واجتماعية معاصرة. وتدور أحداث الرواية حول فتاة تنجرف إلى علاقة عاطفية مع شاب تعرّفت عليه عبر مواقع التواصل الاجتماعى، قبل أن تكتشف لاحقًا أنها وقعت فى أزمة كبيرة قلبت حياتها رأسًا على عقب. كما تتناول الرواية قصة امرأة مسنّة تستعرض سلسلة من الكوارث التى طالت أفرادًا من عائلتها نتيجة هذا النوع من العلاقات، إلى جانب تقديم نماذج وتجارب مختلفة لنساء مررن بظروف مشابهة من خلال إطار جمعية اجتماعية.", "/images/products/9786338387464.webp", "9786338387464", "جيلا", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 580, "محمد مندور", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "رحلة إلى قلب جوجل... حيث تُصنع القمم!\n​تخيّل أنك تملك مفتاحًا ذهبيًا يفتح لك أبواب الصفحة الأولى في جوجل...\nمفتاحًا يسمح لك بالظهور أمام آلاف العملاء في اللحظة التي يبحثون فيها عنك...\nمفتاحًا يجمع بين قوة الإعلانات السريعة وذكاء الظهور المجاني الدائم.\n​في هذا الكتاب، ستدخل معنا إلى غرفة التحكم السرية لجوجل...\nحيث سنكشف لك كيف تعمل خوارزمياته، وكيف تستغلها لصالحك قبل أن يفعل منافسوك.\nستتعلم كيف تطلق حملات إعلانية تخطف الانتباه، وكيف تبني أساسًا صلبًا يجعل جوجل يضعك في القمة... ويبقيك هناك.\n​هنا لن تجد نظريات مملة، بل خططًا عملية وأسرارًا مجربة، لتبدأ رحلتك من الصفر وصولاً إلى الهيمنة على نتائج البحث.\n​🔑 هذه ليست مجرد صفحات... إنها بوابتك لعالم جديد من القوة الرقمية.", "/images/products/9786338387587.webp", "9786338387587", "الكود السرى لجوجل", null, 550m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 581, "محمد مندور", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هل تملك الجرأة لتصبح المسوّق الأعظم؟\nداخل هذا الكتاب تكمن الأسرار التي لا يعرفها سوى القليلون...\n100 قانون، كل واحد منها مفتاح لفهم العملاء، صناعة الثقة، وإطلاق الإبداع الذي يجعل رسالتك لا تُنسى.\nكل اقتباس ليس مجرد نص، بل سلاح سري:\n• يقنع قبل أن يُقرأ،\n• يبني ولاءً قبل أن يُطلب،\n• ويحوّل فكرة صغيرة إلى قصة يرويها الجميع.\nهذا الكتاب هو بوابتك لعالم الإقناع الحقيقي، حيث يصبح الذكاء العاطفي والإبداع أدوات قوة لا يُقاوم لها.\nافتحه، وابدأ رحلة لاكتشاف المسوّق الأعظم الذي بداخلك.", "/images/products/9786338387594.webp", "9786338387594", "قوانين المسوق الأعظم", null, 2000m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 582, "محمد مندور", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في عالمٍ تتحكم فيه الخوارزميات، وتُقاس فيه القيمة بالبيانات، لم يعد التسويق مجرد أداة دعائية، بل أصبح ذكاءً استراتيجيًا يُحدد من يربح السوق ومن يختفي من المشهد.\nنحن لا نعيش ثورة رقمية فقط؛ نحن نعيش عصر الهيمنة الذكية، حيث لا يكفي أن تصل إلى جمهورك — بل يجب أن تفهمه، وتتنبأ بحركته، وتقدّم له الحل قبل أن يشعر بالحاجة إليه.\nمن هنا وُلد هذا الكتاب:\n\"الذكاء التسويقي: دليلك للهيمنة الرقمية\"،\nليكون أكثر من مجرد مرجع، بل نظام تفكير جديد لمن أراد أن يصعد إلى القمة في عالم لا يرحم المتأخرين.\nستأخذك صفحات هذا الكتاب في رحلة عميقة تبدأ من فهم أساسيات التسويق الرقمي، وتمتد إلى أدوات الذكاء الاصطناعي، واستراتيجيات بناء العلامات التجارية، مرورًا بتحليل السلوك، وتخصيص الرسائل، وحتى قيادة حملات تسويقية تنبؤية قائمة على البيانات.\nإنه ليس كتابًا نظريًا، ولا سردًا أكاديميًا جافًا؛ بل هو خارطة طريق عملية، كُتبت بلغة السوق، وعقليّة من يفكّر كقائد رقمي، لا كمجرّد مسوّق.\nإذا كنت تبحث عن التميز في سوق مزدحم، وعن صوت مسموع في عالم صاخب، وعن سيطرة حقيقية على أدوات العصر،\nفهذا الكتاب ليس مجرد اختيار... بل ضرورة.", "/images/products/9786338387600.webp", "9786338387600", "الذكاء التسويقى دليلك للهيمنة الرقمية", null, 450m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 583, "محمد مندور", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هناك أسرار يجب أن تُدفن… وهناك أسرار يُقتل من يقترب منها.\n\nكل شيء بدأ بمعلومة صغيرة…\nملف قديم لا يجب أن يكون موجودًا.\n\nلكن عندما يفتح ياسين هذا الملف، يكتشف أن الحقيقة التي يبحث عنها لم تختفِ…\n\nبل تم محوها عمدًا.\n\nأسماء اختفت من السجلات. حوادث بلا شهود. وأشخاص يتذكرون أشياء… لم تحدث أبدًا.\n\nكل خيط يقوده إلى شبكة من الأسرار تعمل في الظل منذ سنوات. شبكة قادرة على فعل شيء أخطر من القتل…\n\nقادرة على محو الحقيقة نفسها.", "/images/products/9786338387617.webp", "9786338387617", "النسيان", null, 250m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 584, "mohamed mandour", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "What if your entire life... was a sentence written by someone else?\n\nIn a modern Arab city veiled in silence and secrets, former intelligence officer Yassin stumbles upon a manuscript that was never meant to be found.\n\nA forgotten narrative, buried beneath politics and fiction, threatens to unravel not just governments — but reality itself.\n\nAs Yassin digs deeper, he uncovers fragments of a forbidden story: “The First Text” — a mythical document rumored to contain a truth so powerful, it could erase identities, rewrite memory, and dismantle the very concept of history.\n\nWith every chapter, the line between fact and fiction fades.\n\nA mysterious narrator haunts the shadows.\nA woman with eyes full of memory holds the final key.\n\nAnd time begins to collapse... from within the narrative itself.\n\nOblivion is a mind-bending thriller — where espionage meets philosophy, romance dances with danger, and the ultimate conspiracy is not political... but existential.\n\nAre you reading the story?\n\nOr is the story... reading you?", "/images/products/9786338387624.webp", "9786338387624", "OBLivion", null, 250m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 585, "محمد مندور", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "حين يشتبك الحبر بالدم… وتتحول الكلمات إلى معارك لا تقل ضراوة عن الحروب، تبدأ حكاية ظل القمر الأسود.\n\nفي عالمٍ تتداخل فيه الأسرار مع المصير، وتتحرك فيه الخيوط الخفية خلف الأحداث، ينفتح الباب أمام رحلة مشتعلة بالصراع بين الحقيقة والوهم، وبين القوة والقدر. هناك حيث لا تُروى الحكايات فقط… بل تُكتب بدماء أصحابها.\n\n“ظل القمر الأسود – عهد الدم والرماد“ ليست مجرد رواية، بل ملحمة نفسية وإنسانية تكشف عالماً تتصارع فيه النفوس قبل السيوف، وتصبح فيه الكلمة أخطر من الرصاص.\n\nفي كل فصل يزداد الظل عمقاً… وفي كل صفحة يقترب القارئ أكثر من الحقيقة التي قد تغيّر كل شيء.\n\nهل أنت مستعد للدخول إلى العالم الذي لا يخرج منه أحد كما كان؟", "/images/products/9786338387631.webp", "9786338387631", "ظل القمر الأسود عهد الدم والرماد", null, 250m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 586, "محمد مندور", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بعض الملفات لا يجب أن تُفتح…\nوفي عالم الاستخبارات، هناك قاعدة غير مكتوبة:\nإذا اختفى الملف… فهناك من أراد للحقيقة أن تختفي معه.\nعندما يظهر فجأة ملف قديم يحمل الرمز C17، يكتشف بطل الرواية أن الأمر ليس مجرد وثيقة منسية في أرشيف سري.\nبل بداية طريق يقوده إلى شبكة من الأسرار التي دُفنت بعناية… وأشخاص مستعدون لفعل أي شيء حتى تبقى مدفونة.\nكل صفحة من الملف تكشف حقيقة أخطر من السابقة. أسماء لم يكن يجب أن تُذكر. عمليات لم تُسجل رسميًا.\nوأحداث… لم يُسمح للعالم أن يعرف بوقوعها.\nلكن المشكلة الحقيقية ليست في محتوى الملف.\nالمشكلة أن كل من اقترب من الحقيقة قبله… اختفى.\nوالآن أصبح هو التالي في القائمة.\nبين المطاردة، والخداع، والذكريات التي لا يمكن الوثوق بها، يجد نفسه أمام سؤال واحد:\nهل الحقيقة تستحق أن تموت من أجلها؟\n«ملف العميل 17»\nرواية تشويقية استخباراتية مشحونة بالغموض، تكشف عالم الظلال حيث لا شيء كما يبدو… وحيث قد يكون أخطر سلاح في العالم هو المعلومة.", "/images/products/9786338387655.webp", "9786338387655", "ملف العميل 17", null, 200m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 588, "بدور السالم", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ذكريات الماضي إلى حدٍ ما تشبه فيلمًا قديمًا فقد ألوانه، ورغم ذلك لا نزال نحفظه ونشتاقه.\nنشتاق أنفسنا، بيتنا، ومن كان معنا فيها.\nوفي مقطعٍ آخر مهملٍ منها، نجد أنفسنا نشتاق إحساسًا فقدناه مع الكبر.\nإحساس كان حقًّا مستحقًّا للصغار فقط، ومن ثم\nصفعتنا الحقيقة المُرة للكبر… فلم يعد مباح.", "/images/products/9786338387679.webp", "9786338387679", "أنوار", null, 400m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 589, "أحمد سلامة", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ترددت كثيرا أن أكتب هذا الكتاب وأضع خواطرى على الورق ولكن ما شجعنى بعض الشيء أننى كتبت على صفحات التواصل الاجتماعى فوجدت استحسان لا بأس به فقررت أن أجمع ما كتبت فى كتاب واحد لعلى أستطيع أن أرى حجم التجربة واضحا أمامى وعلى الله النتائج والنجاح. ويعود الغرض لكتابة هذا الكتاب إلى أسباب عديدة أولا الكتابة فى حد ذاتها تعد متعة لا توصف وتفريغ لكل الطاقات السلبية والإيجابية داخل الإنسان على الورق والغرض الثانى من هذا الكتاب يعتبر أهم وأخطر الأهداف وهو إقامة الحجة على نفسك. فعندما تريد أن تتصف بصفات أو تطبيق أخلاقيات فبلغها للآخرين فهذا يدفعك إلى التمسك بها وإقامة الحجة على نفسك فيدفعك لتطبيقها. لكنى أعترف أيضا أن هذا الأمر قد لا يكون\nصحيحا فى بعض الأحيان لأن هناك أناس غلبها الشيطان فتكره الخير للناس وتبدأ فى إحباطك والتقليل من شأن ما تعمل فيجب عليك أن تكون مستعدا لهذا ولا تلقي له بالا وأن تبدأ بالأشخاص الإيجابيين الذين يدفعونك للأمام بحب صادق ونية صافية كما أن هناك مقوله رائعة تقول : قل لى وسوف أنسى…. أرنى ربما أتذكر ….. أش ركنى ولن أنس ى للأبد. فإذا أردت أن تتعلم شيئا وتجعله طبعا فيك فأخبره للأخرين وطبقه فيصبح جزءا لا يتجزأ منك وأما الغرض الأخير فهو محاولة صغيرة منى للإسهام فى رفعة\nالأمة والوطن والنصح لدين الله وابتغاء مرضاته. والكتاب عبارة عن خواطرى فى كل شيء وفى كل اتجاه بدءا من الدين والثقافة والرياضة والفن … والعياذ بالله السياسة وأهلها ربنا يجعل كلامنا خفيف عليهم. ولأن طبيعة الناس الآن سريعة الملل فسوف أحاول أن أق ول ما أريد فى جمل سريعة وبسيطة وجمل قليلة. ولهذا سميت الكتاب بإسم خلطبيطة بالصلصة لأنه يشمل الحديث فى كل المجالات تقريبا وبعد التأكد من صدق المعلومات من مصادرها. ويجب أن يعلم الجميع أن محور كتابى يتلخص فى جملة واحدة هى الصلاح لى ولأمتى وفقنا الله لما يحب ويرضى.", "/images/products/9786338387754.webp", "9786338387754", "خلطبيطة بالصلصة", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 590, "عبدالنبى خطاب", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ماذا بعد\nوماذا بعد أن رحلنا\nورسمنا آمالنا\nوماذا بعد أن سرق\nباردُ الليل نبضَ ليالينا\nحتى توارى الليلُ تساؤلَنا\nلِمَ عادت تسألينا\nيا ليلُ الصمتِ مجازينا\nوقد سكنّا متاهاتِ أرواحِنا\nفلتهمسي برفقٍ كيف تنبضُ\nوكيف الليلُ يهدي الحائرينا", "/images/products/9786338387761.webp", "9786338387761", "ماذا بعد", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 591, "أحمد عوارة", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "عارف ال social media news feed ؟\nالمحتوى اللي بيظهرلك كتير ده بيظهر لك ليه؟\nعلشان بتقف عليه بإستمرار .. بتهتم به .. بتتفاعل معاه .. بتتكلم عنه .. بتشاركه\n\nاهو دي دماغك بالظبط .. اللي بتقف عليه .. بتتكلم فيه .. بتشاركه .. بتقوله .. بتديلك منه كتير\n\nوانت اختار .. أي نوع محتوى تحب news feed دماغك تطلع لك منه كتير؟\n\nكلمة mindset بقت تستخد كتير في زماننا وبقينا نقولها كتير, وحتى زعلنا من محمد صلاح لما قال المينتاليتي.", "/images/products/9786338387778.webp", "9786338387778", "العقلية تكسب", null, 400m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 592, "نرمين سمير بيومي", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يسعى الكتاب إلى استكشاف كيف يمكن للذكاء الاصطناعي أن يعيد تشكيل فهمنا للنماذج الإدارية، ويمنحها بعدًا جديدًا أكثر مرونة وواقعية من خلال:\n• تقديم منظورًا جديدًا يجمع بين الفكر الإداري الكلاسيكي والتكنولوجيا الحديثة.\n• مناقشة نموذجًا عمليًا للتخطيط الأستراتيجي (نموذج فايفر) ويعيد تحليله في ضوء أدوات الذكاء الاصطناعي.\n• الربط بين النظرية والتطبيق من خلال حالات دراسية واقعية .\n• مخاطبة الباحثين والمهنيين في مجالات الإدارة، والتخطيط، والتحول الرقمي، ويمنحهم أدوات تحليلية جديدة.", "/images/products/9786338387785.webp", "9786338387785", "التخطيط الأستراتيجي والتحول الرقمي", null, 300m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 593, "علياء احمد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "“منذ مئات السنين، كانت سولارا آخر مدينة للنور. في قلبها، كان يقبع “محراب الشمس”، حيث خُزنت شظية من روح الشمس نفسها.\nلكن الطمع دمر كل شيء… أحد الحراس خاننا وفتح البوابة للظلال. القتال استمر أيامًا، حتى أُطفئ آخر نور، وسقطت الشمس”.", "/images/products/9786338387792.webp", "9786338387792", "رحلة إيلارا", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 594, "أحمد سلامة", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"ترددت كثيرا أن أكتب هذا الكتاب وأضع خواطرى على الورق ولكن ما شجعنى بعض الشيء أننى كتبت على صفحات التواصل الاجتماعى فوجدت استحسان لا بأس به فقررت أن أجمع ما كتبت فى كتاب واحد لعلى أستطيع أن أرى حجم التجربة واضحا أمامى وعلى الله النتائج والنجاح. ويعود الغرض لكتابة هذا الكتاب إلى أسباب عديدة أولا الكتابة فى حد ذاتها تعد متعة لا توصف وتفريغ لكل الطاقات السلبية والإيجابية داخل الإنسان على الورق والغرض الثانى من هذا الكتاب يعتبر أهم وأخطر الأهداف وهو إقامة الحجة على نفسك. فعندما تريد أن تتصف بصفات أو تطبيق أخلاقيات فبلغها للآخرين فهذا يدفعك إلى التمسك بها وإقامة الحجة على نفسك فيدفعك لتطبيقها. لكنى أعترف أيضا أن هذا الأمر قد لا يكون\nصحيحا فى بعض الأحيان لأن هناك أناس غلبها الشيطان فتكره الخير للناس وتبدأ فى إحباطك والتقليل من شأن ما تعمل فيجب عليك أن تكون مستعدا لهذا ولا تلقي له بالا وأن تبدأ بالأشخاص الإيجابيين الذين يدفعونك للأمام بحب صادق ونية صافية كما أن هناك مقوله رائعة تقول : قل لى وسوف أنسى…. أرنى ربما أتذكر ….. أش ركنى ولن أنس ى للأبد. فإذا أردت أن تتعلم شيئا وتجعله طبعا فيك فأخبره للأخرين وطبقه فيصبح جزءا لا يتجزأ منك وأما الغرض الأخير فهو محاولة صغيرة منى للإسهام فى رفعة\nالأمة والوطن والنصح لدين الله وابتغاء مرضاته. والكتاب عبارة عن خواطرى فى كل شيء وفى كل اتجاه بدءا من الدين والثقافة والرياضة والفن … والعياذ بالله السياسة وأهلها ربنا يجعل كلامنا خفيف عليهم. ولأن طبيعة الناس الآن سريعة الملل فسوف أحاول أن أق ول ما أريد فى جمل سريعة وبسيطة وجمل قليلة. ولهذا سميت الكتاب بإسم خلطبيطة بالصلصة لأنه يشمل الحديث فى كل المجالات تقريبا وبعد التأكد من صدق المعلومات من مصادرها. ويجب أن يعلم الجميع أن محور كتابى يتلخص فى جملة واحدة هى الصلاح لى ولأمتى وفقنا الله لما يحب ويرضى.\"", "/images/products/9786338387815.webp", "9786338387815", "خلطبيطة بالصلصة الجزء التاني", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 595, "أحمد فارس", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "حين يصبح الشغف خبزًا،\nوتتحول اللعبة إلى مسرحية هزلية،\nيجد سليم نفسه في عالمٍ أبيض غارق في الطين…\nباحثًا عن حرية قد لا تكون موجودة.", "/images/products/9786338387822.webp", "9786338387822", "مستنقع الحرية", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 596, "أشرف سيد قطب", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أربعة فتيان خرجوا ليلاً، ولم يعودوا كما كانوا،\nفي صيف 1936، لم تكن فلسـطين مسرحاً هادئًا، بل أرضاً يُختبر عليها معنى الرجولة قبل أوانها، كانوا يحملون بنادق أقدم بعقود من أعمارهم، وأحلاماً أثقل من أجسادهم، ويعرفون جيداً أن الطريق الذي اختاروه، لا عودة منه.\nرواية عن المعارك و عن الصداقة حين تُختبر بالدم، وعن الحب الذي يلمع في لحظة احتضار.\nوعن الأب الذي يعطي ابنه المال وهو يعرف أنه ربما يشتري به موته، نحكي عن الثورة قبل أن تصبح شعاراً،\nعن الفتى الذي يدخل الممر وهو لا يعرف إن كان سيخرج منه حيّاً، و إن كان الضوء في نهايته خلاصاً، أم وداعاً.\nلا أبطال خارقين هنا، بل بشر يرتجفون، يترددون، يخطئون،\nثم ينهضون لأن السقوط لم يعد خياراً.", "/images/products/9786338387860.webp", "9786338387860", "ضوء في نهاية الممر", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 597, "حسن شوتى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بينما استمروا في استكشاف الغرفة، وجدوا قطعة معدنية قديمة منقوشة عليها اسم مدينة قديمة كانت مزدهرة قرب البئر، مدينة ربطت بين القبائل كجسر للتواصل والسلام. قال الشيخ الذي حضر معهم ليشارك في هذا الاكتشاف: “هذه المدينة لم تكن مجرد مدينة. كانت فكرة. كانت تعني أننا كنا أمة واحدة.” توقف للحظة ثم أضاف بحزن: “ولكنها دمرت كما دمرنا نحن.”", "/images/products/9786338387877.webp", "9786338387877", "حين تصمت الصحراء", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 599, "فوزى سعيد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "وأدركت أنني لن أشفى.\n\nليس منها فقط، بل من كل شيء.\n\nمن فقدي الأول من غيابي في كل صور العائلة، من شعور الطفل الذي بحث عن ذراع أمه ولم يجدها.\n\nأريد التعلق.... حتى وإن كان هذا سيحطمني.\n\nأنا لست قويًا، ولا ناضجا، ولا متزنا .... أنا هش، هش جدا ، أكثر مما يسمح لي هذا العالم بأن أكون.\n\nوالتعلق بي ليس حبا ....\n\nبل إنقاذ .... ولا أحد ينقذ أحدًا في هذا الزمن.", "/images/products/9786338387907.webp", "9786338387907", "إلينورا", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 600, "سارة سامى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ليس الماضي ما يؤلمنا… بل تلك الوكزة الخفيفة التي يرسلها حين نظن أننا تعافينا.\n“وكز الماضي” حكاية عن جروح ظنناها نامت، فإذا بها تستيقظ عند أول ذكرى، وأول اسم، وأول مواجهة مع أنفسنا.\nرواية تغوص في أعماق النفس، حيث لا يكون الألم صاخبًا، بل صامتًا… أقسى، وأصدق.", "/images/products/9786338387914.webp", "9786338387914", "وكز الماضى", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 601, "فتحى عبدالحميد", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يرافق كتاب حتى إذا بلغ الأربعين القارئ في لحظة فارقة من حياته. لحظة التوقف للمراجعة وإعادة ترتيب الذات. يفتح الكتاب أسئلة العمر والمعنى والمسؤولية. ويحول سن الأربعين من هاجس أو أزمة إلى بداية نضج وانطلاق جديد. موجها رسالته لكل من بلغ الأربعين. أو يقترب منها. أو مر بها دون أن يدرك قيمتها. ليجعل منها محطة وعي وحكمة لا محطة خوف أو انكسار.", "/images/products/9786338387921.webp", "9786338387921", "حتى إذا بلغ الأربعين", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 602, "رضا الشريف", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "التغطية مستمرة ليست حكاية من الماضي، بل تاريخٌ ممتدّ كالجراح المفتوحة في درّة تاج المسلمين.\nهذا العمل لا يروي قصة، بل يكشف حقيقة؛ حقيقة كُتبت بدماء الصغار قبل الكبار، وحاولت قوى الظلام طمسها، لكنها بقيت حيّة.\nمنذ أول صرخة حق، والأرض التي لا تعرف الانكسار تشهد مقاومة لا تهدأ، وذاكرة لا تموت.\nالتغطية مستمرة… لأن الحق لا يُدفن، ولأن التاريخ لا ينسى، ولأن هناك من لا يزال واقفًا ليقول:\nهنا كنّا… وهنا سنبقى.", "/images/products/9786338387952.webp", "9786338387952", "التغطية المستمرة", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 603, "فتحى عبدالحميد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إلى أمل .. رواية تدور حول أب يحرم قسراً من أبنته. فيتحول الفقد الى رحلة كشف طويلة. يكتب فيها رسالته كاعتراف ووصية وشهادة. ومن خلال سرده لتفاصيل الحب والزواج والإنجاب ثم الإنهيار. تفضح الرواية كيف يمكن للقوانين القاسية والتخبيب الأسري وفساد الاعلام ان تصنع مأساة إنسانية كاملة. وتشوه الأبوة. وتغتال المعنى. الرواية ليست مجرد حكاية فقد. بل مواجهة مع الحقيقة. وبحث مؤلم عن العدالة. وتمسك بالأمل رغم الغدر والإنكسار.\nإلى أمل .. كتاب يجعلك تعيد النظر فى كل ما كنت تظنه عدلا.\nوتدرك أن بعض القصص لا تنتهى.\nلأن أصحابها ما زالوا ينتظرون الحقيقة.\nإلى أمل .. قد تكون حكاية لم تكتب بعد.\nأو وجعا يشبه وجعك.", "/images/products/9786338387969.webp", "9786338387969", "إلى أمل", null, 200m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 604, "منه الله مسعود على حسين", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "فكرة خرجت عن الصف، فصارت موضع شك.\nصوت حاول أن يفهم قبل أن يُدان، فحُوصِر بالتصنيفات الجاهزة.\nهنا لا تُروى الأحداث بقدر ما تُفكَّك القناعات،\nولا تُقدَّم الحقيقة كاملة، بل تُترك ناقصة عمدًا،\nلأن الاكتمال أحيانًا شكل آخر من أشكال الكذب.\nما بين الخوف من الاختلاف،\nوالجرأة على التفكير،\nتنكشف المسافة الهشة التي يصنعها المجتمع\nحين يقرّر أي الأفكار تستحق الحياة… وأيّها تُقصى بصمت.", "/images/products/9786338387976.webp", "9786338387976", "رائحة فكرية", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 605, "عمرو عبدالؤوف", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "شرح هندسي لكيفية تأثير الهندسة القديمة على الإسلام، من تصميم المعابد والابنية على الارض مثل تناظر الاهرامات بالجيزة ونجوم حزام الجبار بالسماء\nوتناظر معبد رمسيس الثاني بالاقصر ونجوم العرش بالسماء\nوتناظر الكعبة المشرفة مع نجوم نعش بالسماء\nلنفهم كيف كان يحدد المسلمون الاوائل اتجاه محاريب مساجدهم اثناء الاتجاه للكعبة، لنجيب اخيرا على السؤال الذي حير علماء المسلمين على مدار 1000 عام وتنازعوا حسب الوثائق في اجابته، وهو: لماذا لا تتجه محاريب مساجد الرسول ومساجد الصحابة ومساجد التابعين إلى مكة؟", "/images/products/9786338387983.webp", "9786338387983", "محاربب لا نتجه الى مكة", null, 250m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 606, "حسن مقداد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "“في حروب الصمت، لا يُقاس الدمار بعدد القذائف،\nبل بعدد الأصوات التي لم تُسمَع،\nوالوجوه التي اختفت،\nوالإنسان الذي تُرك وحيدًا بين الألم واللامبالاة.”\n\nحروب الصمت كتابٌ إنساني يوثّق الحرب لا بوصفها مواجهة عسكرية، بل بوصفها تجربة بشرية يومية قد عشتها ويعيشها كل إنسان في غزّة. يسلّط الضوء على ما يسبق القصف وما يليه: الصمت، الخوف، الفقد، التهجير، الأطفال، الخيام، والجوع، في عالمٍ يراقب بصمت.\nلا يبحث الكتاب عن نصرٍ أو هزيمة، ولا يقدّم خطابًا سياسيًا، بل يحاول إنقاذ الذاكرة من النسيان، وكسر الجدار السميك بين المعاناة واللامبالاة، مؤكدًا أن جوهر الحكاية هو الإنسان.. الإنسان فقط.", "/images/products/9786338419028.webp", "9786338419028", "حروب الصمت", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 607, "الشيماء جمعة", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "اندفعت لمكائد وإغراءت جعلتنى فريسة سهل الاستحواذ عليها لم اكن جميلة ولم املك ما يؤهلنى حتى اعيش كما أريد العيش ، بل ذبحت عذريتى على معدة خاوية حتى امتلأت ومن هنا هان كل شىء لم أفكر إلا أن يكسا جسدى وتمتلى معدتتى اسكن فى جحر من جحور العشوائيات كما كنت فى حياة القبور", "/images/products/9786338419035.webp", "9786338419035", "شاعر فى الحقيبة", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 608, "جنة اسماعيل", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تتحدث الرواية عن فتاة فقدت امها، وفتى فقد جدته، والاثنان فقدوا معهم الأمان والحنان، وعند ذهابهم إلى المقبرة لزيارة من فقدوه، ظهر لهم طيفا اخذهم إلى بُعد آخر ، عالم من الإثارة والغموض .", "/images/products/9786338419042.webp", "9786338419042", "الجزء المفقود", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 609, "فاتن على راشد طه", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"ثلاثُ حكاياتٍ تتشابكُ كخيوطِ نولٍ واحد، لكلِّ قلبٍ وجعُه الخفيّ، ولكلِّ روحٍ سرٌّ لا يُروى… وبين ماضٍ يأبى الرحيل، وحاضرٍ يفتح أبواب الاحتمالات، تقفُ الأنثى حائرةً: أتحتمي بذاكرتها، أم تُغامرُ بالنجاة؟\"", "/images/products/9786338419059.webp", "9786338419059", "بين ليالي الوجع (رحلة مليئة بالأسرار)", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 610, "الشيماء جمعة", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أنى احتسى الشراب من أجلك.. انا مجروح فى حبك ،أحببتك بصدق من وهلة، وأنت لا تشعرى بى وتستهزئى بمشاعرى، أسافر دائماً حتى لا ارى شبح زوجك بينى وبينك\n-شعورك هذا منك ولا ذنب أنا فيه ، يعلم الله أعيش معك بكل إخلاص.\n- انظرى لم تنطقى كلمة الحب لأنك لا تخبنى سنوات وسنوات وأنا اغتصب حقى منك حتى فى الكلمة ، وأرى جسد ميت ، مشاعر متجمدة كاليل الشتاء الملىء بالثلوج، أشعر ببكاكوأنا اصطنع النوم بجانبك حتى لا تشعرى بى ، وحياتى تحترق.. قلبى يحترق\n- أنت الذى أساءت فى معاملتك وتعاملت معى كجسد مقتول تكثر به من طعناتك وبخناجرك\nالمسمومة لم تمهلنى أن أشفى من جروحي وقد قلت لك من قبل ، قلبى مازال مهموما وحزينا .", "/images/products/9786338419066.webp", "9786338419066", "ثوب عرس وكفن", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 611, "محمد مندور", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ليست كل الحروب تُخاض في ساحات القتال… بعضها يدور في صمتٍ داخل أعماقنا.\nفي \"الحرب الهادئة – كيف تكسب معاركك الداخلية\" يأخذنا الدكتور محمد مندور في رحلة عميقة إلى داخل النفس البشرية، حيث تدور الصراعات الحقيقية: صراع الخوف، والتردد، والشك، وضجيج الأفكار الذي لا يهدأ.\nهذا الكتاب ليس مجرد كلمات تحفيزية، بل دليل عملي لفهم معاركك الداخلية، واكتشاف القوة الكامنة بداخلك، وبناء عقل أكثر هدوءًا ووعيًا وقدرة على اتخاذ القرار.\nستتعلم كيف:\n• تسيطر على أفكارك بدل أن تسيطر عليك\n• تبني صلابة نفسية في مواجهة الضغوط\n• تحول الصراع الداخلي إلى قوة تدفعك للأمام\n\"الحرب الهادئة\" كتاب لكل من يريد أن ينتصر في أهم معركة في حياته… معركة السيطرة على الذات.", "/images/products/9786338419073.webp", "9786338419073", "الحرب الهادئة", null, 450m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 612, "محمد فكرى محمد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في رأيي أن أشدّ المنتقمين فتكًا هم أولئك الذين حاولوا جاهدين تجنّب خوض المعارك والصدامات، ظنًّا منهم أن ذلك سيمنحهم السلام الذي لطالما سعوا إليه، حتى ولو كان ثمن هذا التجنّب التنازل عن حقوقهم، فقط من أجل أن ينعموا بالسلام ولا شيء غيره. إلا أنهم أدركوا في النهاية أن السلام غاية لا تُدرك ما دمت محاطًا بالبشر؛ فالبشر بارعون جدًا في خلق النزاعات فيما بينهم، وفاشلون جدًا في الحفاظ على السلام، فتحوّلوا إلى منتقمين لا رحمة في قلوبهم، وجعلوا مسعاهم الأول والأخير هو الانتقام ممن سلبهم حقّ السلام.", "/images/products/9786338419127.webp", "9786338419127", "ممالك القيران", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 613, "طه عبدالمحسن", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لم تكن مرورًا عابرًا… بل زلزالًا هادئًا أعاد ترتيب القلب.\nهذا ديوانٌ لا يروي قصة حبٍّ مكتملة، بل يفتح دفاتر اللحظة التي يتغيّر فيها الإنسان للأبد: حين يلمس المعنى، ويخسر اليقين، ويولد الشوق في أبسط التفاصيل.\n\nقصائدُه تمشي على حدِّ الشعور؛ بين حضورٍ يُربك، وغيابٍ يُقيم، وبين كلمةٍ قيلت فأنقذت، وأخرى صمتت فكسرت.\nهنا ستجد نفسك قبل أن تجد الشاعر، وستقرأ بعضك وأنت تظن أنك تقرأ عنه.", "/images/products/9786338419134.webp", "9786338419134", "حين مررت بى", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 614, "كريم عبدالعزيز", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تمنيت يومًا أن تستيقظ وأنت متحمس لبدء يوم عملك؟\nهذا الكتاب ليس مجرد دليل نظري، بل رفيقك العملي لإعادة اكتشاف السعادة في بيئة عملك، بخطوات واقعية، سهلة، وفعّالة.\nسنتعلم معًا كيف نخفف الضغوط، ونستعيد الشغف، ونبني توازنًا حقيقيًا بين الإنجاز والراحة، بين الإنتاجية والرضا.\nمن تقنيات الامتنان والتنفس الواعي، إلى طرق التعامل مع الزملاء والبيئات المرهقة… هذا الكتاب كُتب لك، لتمنح نفسك ما تستحق: راحة البال، والتحفيز، وسعادة العمل.\nلا شعارات… لا مثالية زائفة… فقط أدوات حقيقية تمنحك السيطرة على وقتك، طاقتك، ومزاجك.\nاقلب الصفحة، وابدأ رحلتك نحو يوم عمل يليق بك.", "/images/products/9786338419141.webp", "9786338419141", "سعيد فى عملى", null, 250m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 615, "طه عبد المحسن", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ما تبقّى من آدم\nحين يصبح البقاء اختبارًا للإنسانية، لا للجسد.\nقصة تكشف كيف يمكن للعالم أن يسرق منا كل شيء… إلا السؤال الأخير:\nماذا بقي فينا لنُسمّى بشرًا؟\n\nنصٌّ قصير في حجمه، عميق في وجعه،\nتدخل صفحاته وأنت تبحث عن آدم،\nوتخرج منها وأنت تتمنى أن تكون ما تبقّى منه.", "/images/products/9786338419158.webp", "9786338419158", "ما تبقى من ادم", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 616, "محمد فكرى محمد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"سماء صافية، وشمس تسللت خيوطها عبر النافذة الصغيرة لغرفة داليا لتلامس وجهها الملائكي النائم في هدوء، فأصدر المنبه صوتًا عاليًا جعلها تفتح عينيها العسلية الواسعة، ثم قامت بالضغط عليه لتسكته قبل أن تعتدل من نومها وتنهض.\"", "/images/products/9786338419165.webp", "9786338419165", "حلم طنجار", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 617, "محمود النجار", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ليس هذا الكتاب سيرة ذاتية بالمعنى التقليدي، ولا بحثًا أكاديميًا باردًا، ولا شهادة إنسانية عابرة تُكتب بدافع الألم فقط. إنه محاولة واعية لالتقاط لحظة تاريخية نادرة: لحظة يولد فيها الوعي من قلب الفقد، وتُعاد فيها صياغة المعرفة تحت الركام.\nكُتب هذا الكتاب في زمن لم تعد فيه الأسئلة النظرية منفصلة عن الدم، ولم يعد فيه الكاتب قادرًا على الاحتماء خلف حياد زائف أو لغة محايدة. في زمن الإبادة، يصبح الصمت موقفًا، ويغدو البحث إما فعل مسؤولية أو شريكًا في التواطؤ. من هنا، لا يقدم هذا الكتاب إجابات جاهزة، بل يطرح أسئلة أخلاقية ومعرفية عميقة حول دور الإنسان، والكاتب، والتقنية، والمعرفة في عالم تتآكل فيه القيم أمام آلة العنف.", "/images/products/9786338419172.webp", "9786338419172", "من تحت الركام ولد الوعي", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 618, "Mohmoud ElNaggar", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "This book is neither an autobiography in the conventional sense, nor a cold academic study, nor a fleeting humanitarian testimony written solely under the weight of pain. Rather, it is a conscious attempt to capture a rare historical moment: a moment in which awareness is born from the heart of loss, and knowledge is reformulated beneath the rubble.\nThis book was written at a time when theoretical questions are no longer separable from blood, and when the writer can no longer take refuge behind false neutrality or detached language. In an era of genocide, silence becomes a position, and research becomes either an act of responsibility or a partner in complicity. Accordingly, this book does not offer ready-made answers; instead, it raises profound ethical and epistemological questions about the role of the human being, the writer, technology, and knowledge in a world where values are eroded by the machinery of violence.", "/images/products/9786338419189.webp", "9786338419189", "From Beath The Rubble Awareness Was Born", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 619, "محمد بكر مشتهرى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كان بين الركاب إمرأة حامل تدعى “أمل” على وشك الولادة كانت ذاهبة للمتابعة مع المستشفى ولم تتحمل أمل هذه المعناه وبالفعل ولدت “أمل” بمساعدة السيدات المتوجدات بالمترو والمفاجأة التي أذهلت الجميع هو شكل الطفل الغريب فكانت رأسه رأس إنسان مشوه جدًا وهيئة جسمه غريبة يكسوه شعر كثيف عيناه جاحِظتان وفمه وأنفاسه يخرجان منهما حرارة غريبة تُحرق كل من يقترب منه والأغرب من ذلك هو أنه يستطيع أن يحبوا وهو حديث الولادة ! وطريقته تشبه الروبوت مما تسبب فى حالة ذُعر بين ركاب المترو الصراخ هنا وهناك ودخلت أمل فى نوبة هيسترية .", "/images/products/9786338419196.webp", "9786338419196", "أوكتافا", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 620, "شادي محمد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "العمل أصلي بالكامل، ولا يتضمن أي اقتباسات حرفية من كتب أخرى، وإنما يعتمد على قراءة نقدية ورؤية فكرية خاصة بالمؤلف، نابعة من التحليل والتجربة الشخصية، دون نقل أو اعتماد مباشر على مصدر بعينه.\n«لم أقترب من طه حسين لأهدمه،\nبل لأنزله من مقام العصمة إلى مساحة الإنسان…\nحيث يخطئ الكبار كما يُلهمون.»", "/images/products/9786338419202.webp", "9786338419202", "قراءة فى كبرياء الأيام", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 622, "محمد صبرى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ماذا لو كان الموت هو الكذبة التي عشتها لثلاثين عامًا؟\n​في لحظة واحدة يتحول عزاء السنين إلى سراب، وتعود أشباح الماضي لتطرق الباب بمفتاحٍ صغير ورسالة مستحيلة من عالم الأموات.\n​بين ذكريات البراءة ودهاليز الجريمة تدور رحلةُ بحثٍ تحبس الأنفاس عن هويةٍ ضائعة وحقٍ مسلوب.\nحين يدق “الجرس” تأكد أن الصدى سيغير كل شيء.\n​هل أنت مستعد لمواجهة الحقيقة؟", "/images/products/9786338419226.webp", "9786338419226", "جرس", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 623, "ياسمين اسماعيل", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "عندما يتوارى البدر، وتظهر بنات نعش الكبرى، اربط الدليلين، تجد الجدي عند البوابة، وبعد استقرار الشمس بمثواها، تُفتح المقبرة.\nلغز تناقلته الأجيال عن أسطورة\nبقبر غامض رقدت أسرارها.\nمغامرين كثر سعوا لكشف أخبارها،\nأهلكتهم رينينا على عتبات أطلالها.\nحتى… أتى حملة عهدها\nولامس الجعران نقشها\nفاستيقظ الأحمر نهمًا للدماء\nيبحث عن دمًى آدمية\nيبث رعبه بالقلوب عبرها\nوانبعثت شياطين الكندافيت\nتلقي التعاويذ لتشعل شرارة حرب ضد أعدائها.", "/images/products/9786338419233.webp", "9786338419233", "رينينا", null, 200m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 624, "مريم محمود الدالى", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "قد تظن للوهلة الأولى أن هذا الكتاب موجَّه لمرحلة بعينها، لكنه في الحقيقة يخاطب كل قارئ يبحث عن ذاته، ويسعى لفهم نفسه، وبناء طريقه بوعي وثقة، فكل كلمة هنا كُتبت لتكون رفيقًا لك في رحلتك، تختصر عليك الكثير من الطرق المتعرجة، وتفتح أمامك آفاقًا أوسع، فهو خلاصة مسارات متشابكة، ومحطات من التخبط والاكتشاف.", "/images/products/9786338419240.webp", "9786338419240", "رحلة وعى", null, 100m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 625, "إسراء ساهر", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ليست كل المعارك تُخاض بالسلاح…\nبعضها يبدأ حين تكتشف أن أكثر ما يطاردك ليس ما تراه، بل ما تحمله داخلك.\nفي قلب العاصفة المظلمة، تتداخل الحقيقة مع الوهم، ويتحوّل الخوف إلى اختبار، والنجاة إلى اختيار له ثمن.\nرواية عن لحظة واحدة قد تغيّر كل شيء، وعن شجاعة الوقوف في وجه الظل حين يصبح الهروب مستحيلًا.\n\n\"حين أدركت أن العاصفة لم تكن حولي بل داخلي، عرفت أن النجاة لن تكون بالهرب… بل بالمواجهة.”", "/images/products/9786338419257.webp", "9786338419257", "قلب العاصفة المظلمة", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 626, "شروق الهامى الحديدى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"رفع رأسه ببطء وهو يتأوه، بصق شيئاً شعر به بفمه ممزوجاً بسائلٍ ظنَه لعابَه حتى رآه على الأرض بجانب جسده المسجيِّ على الرمال البيضاء، كان أحد الضروس مكسوراً ومختلطاً بالرمال والدماء. تحسس بلسانه أسنانَه ليعرف مكانه لعجزه عن تبين مكانه استدلالاً بالألم، فكل وجهه وجسده يؤلمانه بشدة.\n\nاعتدل جالساً ونظر حوله، ففزع حين رأى أنه في مكان مقفر لا يوجد به سواه، فلاة ممتدة علي مرمى بصره، حاول الوقوف ولكن ساقه اليسري لم تُعِنه، بل على العكس زاد توجعُه منها على بقية الجسد بشكلٍ لفت نظره لتخضب بنطاله بالدماء، فرضخ وعاد للجلوس جاهلاً ما يمكن أن يقوم به أو يساعده في الورطة التي وجد نفسه فيها.\"", "/images/products/9786338419264.webp", "9786338419264", "أبواب", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 627, "شيماء بركات", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "وطلعت بسرق ياهوى\nالكحل من قلب العيون\nوانا مش بخون\nكل اللي حبوني بفؤادهم\nعمري ليهم ولراحتهم\nاسهر واشيل\nواميل لو مره يحتاجوا\nاكون عُكاز\nانا مش ازاز\nعلشان تحدفوني بطوب\nأنا شخص كله عيوب\nوحاجات كمان حلوه\nواما اجي اقول غنوه\nمبقولش بالتفاصيل", "/images/products/9786338419288.webp", "9786338419288", "قلب مفطوم على البكا", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 628, "إسراء محمود حلمى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "وكأني أعرف القراء عن كثب بينهم المازح والعابس والضاحك والباكي والمحب وكل واحدآ منهم له قصته في هذا الكتاب وستتلقى معي أيها القارئ سيلآ متواصلآ من المشاعر و ستجدني أرحل معك من قصة إلى قصة ومن حبكة درامية لحبكى أخرى أكثر تأثيرآ وكان هدفي الأكبر هو محاكاة الواقع ولكن وجدت الخيال يلوح لي من بعيد ليعيد إلى قلمي جمال الخيال مرة أخري .", "/images/products/9786338419295.webp", "9786338419295", "قصة واحدة لا تكفى", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 629, "فريق عمل تصميماتى / شهيرة المصرى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "“أُعد هذا الكتاب ليكون مرجعًا عمليًا لتعليم التصميم على الهاتف، وذلك بطريقة مبسطة وسهلة التطبيق.\nالهدف منه تمكين أي شخص من تحويل خياله إلى تصميم جميل دون الحاجة إلى أجهزة متقدمة أو برامج معقدة.\nستجد في صفحاته شرحًا للأدوات، وخطوات التصميم، وأمثلة تطبيقية تساعدك على تطوير مهاراتك تدريجيًا.”", "/images/products/9786338419301.webp", "9786338419301", "تصميماتى", null, 250m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 632, "محمود سعد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدور أحداث الرواية حول تقنية ثورية تعتمد على شريحة نانو تُزرع في عقل الإنسان بدعوى علاج الأمراض العصبية وتحسين القدرات الذهنية، مثل الذاكرة، وسرعة التعلم، والتحكم في الألم والمشاعر.\nفي البداية تُقدَّم الشريحة على أنها أعظم إنجاز علمي يخدم البشرية، وتُستخدم على نطاق محدود ثم تتوسع تدريجيًا حتى تصبح خيارًا شبه إلزامي.\nمع الوقت، يكتشف أبطال الرواية أن الشريحة لا تكتفي بالمراقبة الطبية، بل تسجّل الأفكار، وتعدّل المشاعر، وتعيد توجيه القرارات دون وعي أصحابها. تتحول الحدود بين الإرادة الحرة والبرمجة إلى خط ضبابي", "/images/products/9786338419332.webp", "9786338419332", "الشريحة", null, 160m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 633, "طه ثابت", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "استعد لرحلة اكتشاف الطاقة المفقودة بداخلك، وكن جاهزًا للأحداث التي قد تطرق بابك، أوعدك بالإستمتاع بالرحلة طالما نظرت لأمور حياتك بشكل منطقي دون الإرتباط بمشاعرك، بالتأكيد ستكون الرحله صعبة، إنك سَتبحر في أعماق نفسك لتكتشف ماذا يحدث بداخلك، وما هى المتاعب التي تستهلك طاقتك لتقضي عليها تمامًا، ثم تُرمم تلك الندوب التي تركتها؛ لتنقذ نفسك من البؤس القاتل، كن حَذرًا من الإبحار في هذا المكان الخاطيء، ولا تكون مثل الصياد الذي ترك البحر وذهب بشبكته إلى الصحراء؛ ليصطاد منها جميع المتاعب التي تقضي عليه لا محال.", "/images/products/9786338419349.webp", "9786338419349", "الطاقة المفقودة", null, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 634, "محمد مندور", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ماذا لو لم يكن الشفاء نعمة… بل صفقة؟\n\nالصيدلية تظهر حين تكون في أضعف حالاتك،\nتدخلها باحثًا عن الخلاص،\nوتخرج منها حاملًا سؤالًا لن يتركك:\n\nإذا كان نجاتك مرهونة بسقوط غيرك… فهل تختار الشفاء؟\n\nهذه ليست رواية رعب،\nبل مواجهة مع ضميرك،\nوإن بدأت القراءة…\n\nتذكر: ليس كل باب يُفتح… يريدك أن تعود.", "/images/products/9786338419356.webp", "9786338419356", "الصيدلية", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 635, "محمد ابو السعود", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في عالمٍ تتسارع فيه تدفّقات المعلومات، وتتداخل فيه الحقيقة بالوهم، يبرز الاستهواء الفكري بوصفه إحدى أخطر الظواهر التي تهدد وعي الفرد وتماسك المجتمع، لاسيما في أوساط الشباب، يأتي هذا الكتاب ليقدّم معالجة علمية وتحليلًا معمقًا لهذه الظاهرة، كاشفًا عن آلياتها الخفية، ومظاهرها المتعددة، وآثارها السلبية الممتدة على التفكير والسلوك واتخاذ القرار، وينطلق الكتاب من تأصيلٍ مفاهيمي دقيق لظاهرة الاستهواء الفكري، موضحًا أبرز مظاهرها لدى الفرد، وما تخلّفه من نتائج نفسية ومعرفية وسلوكية، مثل تراجع التفكير النقدي، والانقياد غير الواعي للأفكار المتطرفة أو المضللة، وفقدان الاستقلالية الفكرية، كما يستعرض مجموعة من النظريات النفسية والاجتماعية المفسّرة للاستهواء الفكري، ويحلل العوامل المؤثرة فيه، سواء تلك المرتبطة بخصائص الفرد النفسية والمعرفية، أو بالعوامل الاجتماعية والثقافية المحيطة به، كما يولي الكتاب اهتمامًا بدراسة العلاقة بين ظاهرة الاستهواء الفكري والاستخدام المكثف لمواقع التواصل الاجتماعي، مبرزًا دور هذه المنصات في إعادة تشكيل الوعي، وتسريع انتشار الأفكار الموجَّهة، وتعميق دوائر التأثير عبر الخوارزميات والمحتوى العاطفي والمعلومات غير الموثوقة، ولا يقتصر الكتاب على تشخيص الظاهرة وتحليلها، بل ينتقل إلى الجانب التطبيقي، حيث يقدّم مجموعة من الاستراتيجيات العملية التي تمكّن الفرد من التصدي للاستهواء الفكري، في مقدمتها تنمية مهارات التفكير الناقد، بوصفه أداة أساسية للفحص والتحليل والتمييز بين الحقيقة والتضليل، إلى جانب تعزيز المناعة النفسية بما تحمله من قدرة على الصمود، وضبط الانفعالات، ومقاومة الضغوط الفكرية والاجتماعية، كما يوسّع الكتاب دائرة المواجهة لتشمل الأدوار التربوية والمجتمعية، فيناقش دور الأسرة في بناء الوعي المبكر لدى الأبناء، ودور المدرسة في ترسيخ مهارات التفكير الواعي والمسؤول، ودور الجامعة في حماية العقول الشابة من الانجراف الفكري، وتعزيز الاستقلالية الفكرية والانتماء الواعي، وعليه يهدف المؤلف من خلال هذا العمل إلى تمكين القارئ من فهم ظاهرة الاستهواء الفكري بعمق، وتزويده بالأدوات الفكرية والنفسية التي تحمي وعيه من الاختطاف، ليصبح أكثر قدرة على تحليل الأفكار والمعلومات، واتخاذ قراراته باستقلالية، وخوض تجربة معرفية حرة ومستنيرة في زمن تتكاثر فيه محاولات التأثير والسيطرة على العقول.", "/images/products/9786338419363.webp", "9786338419363", "الوعى المختطف", null, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 444, "داليا محمد محمود", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "عندما تصل خريطة قديمة وغامضة إلى أيدي فريق المستكشفين، يجد القائد الشجاع \"بدر\"، والفنانة الحالمة \"ليلى\"، والعبقري الصغير \"سامر\" أنفسهم في مواجهة لغز عمره قرون. تقودهم الخريطة إلى قلعة مهجورة على أطراف المدينة، مكان تحوم حوله الأساطير وتتردد في أروقته أصداء الماضي.\n\nبمساعدة الشرطي أحمد وكلبه الوفي \"برق\"، يكتشف الفريق أنهم ليسوا وحدهم من يبحث عن سر القلعة. ففي الظل، يتربص بهم لص غامض يسعى للوصول إلى الكنز قبلهم. بين الممرات السرية، والأفخاخ المنسية، والألغاز المحيرة، هل سينجح فريق المستكشفين في كشف الحقيقة قبل فوات الأوان؟ مغامرة مثيرة عن الشجاعة والصداقة وكشف أسرار الماضي.\n\nداليا محمد محمود", "/images/products/9786339972119.webp", "9786339972119", "سلسلة فريق المستكشفين", null, 100m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 448, "مى خفاجة", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في مدينة جميلة يحيط بها الشلال من كل جانب، تتميز المدينة ببحيرة لها قوة الشفاء والراحة من كل ما يشغل البال. مدينة تزهو بأنواع نادرة من الورود والأعشاب، يقع في حبها كل من يعبر عتباتها أو يمر بها.\nيحكمها ملك قاسٍ على ابنته، مهمل في حكمه، ويترك أمور الحكم لوزيره الذي أفسد المدينة وجعل الرعايا ينامون ليلهم دون لقمة تسند عليها معدتهم المسكينة وتسد جوعهم.", "/images/products/9786339972164.webp", "9786339972164", "سر جوهرة البحيرة", null, 100m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 453, "محمد نجيب مطر", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بقي مشروع الدكتور نادر حبيس الأدراج، وحقول القمح المستورد تملأ الأسواق. بقي المزارعون يعانون من ملوحة أراضيهم، وبقي الوطن يعتمد على الخارج في غذائه الأساسي. وقف الدكتور نادر أمام نبات القمح المعدل وراثيًا في مختبره، ينظر إليه بحسرة وأمل خافت، متمنيًا أن يأتي يوم يقدر فيه وطنه قيمة العلم والابتكار، ويستفيد من كنوز الأرض حتى لو كانت مروية بماء البحر.", "/images/products/9786339972508.webp", "9786339972508", "عروض مسرحية للأطفال", null, 100m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 464, "بكر صابر على على", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مجموعة مسرحية بعنوان \"وصايا الطريق ومسرحيات أخرى للأطفال\"، وتضم نصوصاً درامية تعليمية وتربوية موجهة للناشئة، تتنوع موضوعاتها بين القصص الرمزية على ألسنة الحيوانات، والدراما التاريخية، والاجتماعية.\nتتميز هذه المجموعة بالتركيز على غرس القيم الأخلاقية، وتعزيز الهوية الوطنية، وتقديم نماذج إيجابية للتحدي والإصرار.", "/images/products/9786339974045.webp", "9786339974045", "وصايا الطريق ومسرحيات أخرى لأطفال", null, 120m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 469, "وئام عادل", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "حكي القصة عن الطفل أحمد، البالغ من العمر تسع سنوات، الذي يواجه تحدي مرض السكري من النوع الأول، لكنه يتغلب عليه بمساعدة صديقه الوفي لاكي، الكلب المدرَّب على استشعار انخفاض مستوى السكر في الدم. من خلال مغامرات مدرسية ويومية مؤثرة، يظهر لاكي بطولته في إنقاذ أحمد في المواقف الصعبة، سواء في الغابة أو وسط الزحام في السوق. مع مرور الوقت، يتعلم أحمد تقبّل مرضه بثقة، ويشارك تجربته مع أصدقائه، مؤكدًا أن البطولة الحقيقية تكمن في الصداقة، الوفاء، والإيمان بالذات.\n\nالقصة تبرز قيم الشجاعة، الصداقة، المسؤولية، والتعايش مع التحديات الصحية بلغة إنسانية وملهمة للأطفال واليافعين.", "/images/products/9786338367008.webp", "9786338367008", "صديقى لاكى", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 471, "وئام عادل", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدور أحداث القصة حول الطفلة وئام وأرنبها الأبيض جَزَر، اللذين يعبران من خلال باب سحري خلف شجيرة الياسمين إلى عالم خيالي يسمى أرض الفراشات المضيئة. هناك تكلَّفهما الفراشات بمهمة إنقاذ أرض النور من قوى الظلام بعد اختفاء الفراشة الأم. تخوض وئام وصديقها مغامرات مدهشة بين الكهوف والغابات والجبال والصحارى، ويواجهان مخلوقات عجيبة ويتغلبان على المخاطر بالشجاعة والصدق ونقاء القلب. في النهاية، يحرران الفراشة الأم ويعيدان النور والبهجة إلى المملكة، ثم تعود وئام إلى عالمها حاملة زهرة أمل مضيئة تذكرها دومًا بأن الخيال مفتاح السعادة.\n\nالقصة تمزج بين الخيال الطفولي البهيج والقيم الإنسانية كالطيبة، الصداقة، الأمل، والشجاعة، لتفتح أمام الطفل أبواب الحلم والإبداع.", "/images/products/9786338367022.webp", "9786338367022", "ؤئام وجذر في أرض الفراشات", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 475, "أم محمد عياطي", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ارتأيت أن أستوحي من عمق الحبكات التي تتضمنها قصص كليلة ودمنة المتنوعة موضوعات سائغة ندية لأطفالنا وأقدمها في شكل مسرحيات مبسطة في أسلوبها عميقة في إفادتها و مراميها لأجل غرس مبادئ إيمانية وتربوية هادفة، كل ذلك ملفوفا في رداء أدبي ممتع وراق يغذي شغف الطفل ويروي فضوله المتطلع دوما لمعرفة كل ما هو جميل و جديد", "/images/products/9786338367077.webp", "9786338367077", "مسرحيات كليلة ودمنة لأطفال", null, 100m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 487, "عيد صلاح", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "عالم مثير ومدهش ومجتمع منظم؛ يعمل في تناسق عجيب؛ أحب علاء أن يدخل إلى هذا العالم الجميل المثير ويكتشف أسراره، فماذا فعل.. تعالوا معا نتعرف على هذه القصة الجميلة..\nالمؤلف\nعيد صلاح", "/images/products/9786338367282.webp", "9786338367282", "قصة النحل", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 488, "شاكر صبرى", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "سلسلة حيوانات ذكرت في القرآن الكريم، يحتوي عشرة قصص موجهة للأطفال للمرحلة السنية من 6-12 سنة بأسلوبٍ بسيط وسهلٍ حتَّى يَستطيعَ الطِّفْلُ أنْ يَسْتَوْعِبها.\n\nقصص القرآن جميلة وتحتوي علي معاني وقيم هادفة للكبار والصِّغارِ علَي حَدٍّ سَواءٍ.\n\nنحن نحتاج أن نعمق معرفة أطفالنا بدينهم ونربطهم أكثرَ بالتُّراثِ الدِّيني بِأُسلوبٍ يَجذِبُ انْتباهَهمْ ويُثيرُ مَشاعِرهُمْ.", "/images/products/9786338367305.webp", "9786338367305", "هدهد سيدنا سليمان", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 496, "شاكر صبرى", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"سلسلة حيوانات ذكرت في القرآن الكريم، يحتوي عشرة قصص موجهة للأطفال للمرحلة السنية من 6-12 سنة بأسلوبٍ بسيط وسهلٍ حتَّى يَستطيعَ الطِّفْلُ أنْ يَسْتَوْعِبها.\n\nقصص القرآن جميلة وتحتوي علي معاني وقيم هادفة للكبار والصِّغارِ علَي حَدٍّ سَواءٍ.\n\nنحن نحتاج أن نعمق معرفة أطفالنا بدينهم ونربطهم أكثرَ بالتُّراثِ الدِّيني بِأُسلوبٍ يَجذِبُ انْتباهَهمْ ويُثيرُ مَشاعِرهُمْ.\"", "/images/products/9786338367404.webp", "9786338367404", "حوت نبى الله يونس (سلسلة حيوانات ذكرت في القرآن الكريم)", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
