                    { 500, "شاكر صبرى", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"سلسلة حيوانات ذكرت في القرآن الكريم، يحتوي عشرة قصص موجهة للأطفال للمرحلة السنية من 6-12 سنة بأسلوبٍ بسيط وسهلٍ حتَّى يَستطيعَ الطِّفْلُ أنْ يَسْتَوْعِبها.\n\nقصص القرآن جميلة وتحتوي علي معاني وقيم هادفة للكبار والصِّغارِ علَي حَدٍّ سَواءٍ.\n\nنحن نحتاج أن نعمق معرفة أطفالنا بدينهم ونربطهم أكثرَ بالتُّراثِ الدِّيني بِأُسلوبٍ يَجذِبُ انْتباهَهمْ ويُثيرُ مَشاعِرهُمْ.\"", "/images/products/9786338367459.webp", "9786338367459", "(كلب أصحاب الكهف) سلسلة حيوانات ذكرت في القرآن الكريم", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 501, "شاكر صبرى", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"سلسلة حيوانات ذكرت في القرآن الكريم، يحتوي عشرة قصص موجهة للأطفال للمرحلة السنية من 6-12 سنة بأسلوبٍ بسيط وسهلٍ حتَّى يَستطيعَ الطِّفْلُ أنْ يَسْتَوْعِبها.\n\nقصص القرآن جميلة وتحتوي علي معاني وقيم هادفة للكبار والصِّغارِ علَي حَدٍّ سَواءٍ.\n\nنحن نحتاج أن نعمق معرفة أطفالنا بدينهم ونربطهم أكثرَ بالتُّراثِ الدِّيني بِأُسلوبٍ يَجذِبُ انْتباهَهمْ ويُثيرُ مَشاعِرهُمْ.\"", "/images/products/9786338367466.webp", "9786338367466", "(ناقة نبى الله صالح) سلسلة حيوانات ذكرت في القرآن الكريم", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 504, "شاكر صبرى", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"\"\"سلسلة حيوانات ذكرت في القرآن الكريم، يحتوي عشرة قصص موجهة للأطفال للمرحلة السنية من 6-12 سنة بأسلوبٍ بسيط وسهلٍ حتَّى يَستطيعَ الطِّفْلُ أنْ يَسْتَوْعِبها.\n\nقصص القرآن جميلة وتحتوي علي معاني وقيم هادفة للكبار والصِّغارِ علَي حَدٍّ سَواءٍ.\n\nنحن نحتاج أن نعمق معرفة أطفالنا بدينهم ونربطهم أكثرَ بالتُّراثِ الدِّيني بِأُسلوبٍ يَجذِبُ انْتباهَهمْ ويُثيرُ مَشاعِرهُمْ.\"\"\"", "/images/products/9786338367497.webp", "9786338367497", "فيل أبرهة الحبشي سلسلة حيوانات ذكرت في القرآن الكريم", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 506, "شاكر صبرى", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"\"\"\"\"\"\"سلسلة حيوانات ذكرت في القرآن الكريم، يحتوي عشرة قصص موجهة للأطفال للمرحلة السنية من 6-12 سنة بأسلوبٍ بسيط وسهلٍ حتَّى يَستطيعَ الطِّفْلُ أنْ يَسْتَوْعِبها.\n\nقصص القرآن جميلة وتحتوي علي معاني وقيم هادفة للكبار والصِّغارِ علَي حَدٍّ سَواءٍ.\n\nنحن نحتاج أن نعمق معرفة أطفالنا بدينهم ونربطهم أكثرَ بالتُّراثِ الدِّيني بِأُسلوبٍ يَجذِبُ انْتباهَهمْ ويُثيرُ مَشاعِرهُمْ.\"\"\"\"\"\"\"", "/images/products/9786338367534.webp", "9786338367534", "عصا نبي الله موسى التي تحولت إلى حية سلسلة حيوانات ذكرت في القرآن الكريم", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 507, "إسراء كمال", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "قطقوطة قطة شقية، بتغلب ماما وبابا، وبتعمل مصايب أكبر منها، وبإبتسامة ماما وبابا بينسوا للمصيبة الجاية، مع نصيحة حلوة جميلة بعد كل مغامرة.", "/images/products/9786338367541.webp", "9786338367541", "مغامرات قطقوقة", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 514, "غالية يونس محمد", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"قصة ممتعة وهادفة تأخذ الأطفال في رحلة شيّقة مليئة بالمواقف البسيطة والمعاني العميقة، حيث يتعلّمون من خلالها قيَمًا جميلة مثل الصدق، والتعاون، وتحمل المسؤولية. بأسلوب سهل ومحبّب، تساعد القصة الصغار على تنمية خيالهم وتعزيز سلوكياتهم الإيجابية بطريقة ممتعة وشيّقة.\"", "/images/products/9786338367640.webp", "9786338367640", "بطوطة و بطيطة", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 515, "غالية يونس محمد", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"قصة ممتعة وهادفة تأخذ الأطفال في رحلة شيّقة مليئة بالمواقف البسيطة والمعاني العميقة، حيث يتعلّمون من خلالها قيَمًا جميلة مثل الصدق، والتعاون، وتحمل المسؤولية. بأسلوب سهل ومحبّب، تساعد القصة الصغار على تنمية خيالهم وتعزيز سلوكياتهم الإيجابية بطريقة ممتعة وشيّقة.\"", "/images/products/9786338367657.webp", "9786338367657", "أرنوبة و سلة الجزر", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 516, "غاليه يونس محمد", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"قصة ممتعة وهادفة تأخذ الأطفال في رحلة شيّقة مليئة بالمواقف البسيطة والمعاني العميقة، حيث يتعلّمون من خلالها قيَمًا جميلة مثل الصدق، والتعاون، وتحمل المسؤولية. بأسلوب سهل ومحبّب، تساعد القصة الصغار على تنمية خيالهم وتعزيز سلوكياتهم الإيجابية بطريقة ممتعة وشيّقة.\"", "/images/products/9786338367664.webp", "9786338367664", "أرنوب الصغير و كذبنة الصغيرة", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 517, "غاليه يونس محمد", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"قصة ممتعة وهادفة تأخذ الأطفال في رحلة شيّقة مليئة بالمواقف البسيطة والمعاني العميقة، حيث يتعلّمون من خلالها قيَمًا جميلة مثل الصدق، والتعاون، وتحمل المسؤولية. بأسلوب سهل ومحبّب، تساعد القصة الصغار على تنمية خيالهم وتعزيز سلوكياتهم الإيجابية بطريقة ممتعة وشيّقة.\"", "/images/products/9786338367671.webp", "9786338367671", "نمولة و قطعة الحلوى", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 518, "غاليه يونس محمد", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"قصة ممتعة وهادفة تأخذ الأطفال في رحلة شيّقة مليئة بالمواقف البسيطة والمعاني العميقة، حيث يتعلّمون من خلالها قيَمًا جميلة مثل الصدق، والتعاون، وتحمل المسؤولية. بأسلوب سهل ومحبّب، تساعد القصة الصغار على تنمية خيالهم وتعزيز سلوكياتهم الإيجابية بطريقة ممتعة وشيّقة.\"", "/images/products/9786338367688.webp", "9786338367688", "من أخذ تاج الملك؟", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 520, "سحر دغيدى", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في عالمنا الكبير نحتاج إلى هواء نقي وبيئة سليمة دون أن نفسد جمالها أو نظامها الذي خلقه الله لنعيش في صحة أفضل ونرى جمال صنع الخالق في كل شيء.", "/images/products/9786338367725.webp", "9786338367725", "عمر و الشجرة", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 523, "إيمان فريد", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كان أمين الرجل الفقير جارا لرشيد الذي يمتلك بستانا للفواكه ولكنه يعيش وحيدا مع زوجته بلا أولاد، وقد اعتاد أن يعطي لأمين جزءا من الثمار التي يجنيها كل يوم حتى يبيعها في السوق ويستطيع إعالة أبنائه الصغار، وذات يوم تغيّب رشيد عن عمله واحتار أمين ماذا يفعل؟ ترى ماذا ألمّ برشيد؟ وما سرّ غيابه؟ وكيف تصرّف أمين في تلك الورطة؟", "/images/products/9786338367770.webp", "9786338367770", "الجار الأمين و بستان الفواكه", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 524, "آيات خلف صابر", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ماذا لو كان الخوف هو أول خطوة نحو الشجاعة؟\nتحكي قصة زرّو وعُشبة الشجاعة عن أرنب صغير يخاف من كل شيء، لكنه يكتشف أن الشجاعة الحقيقية لا تعني غياب الخوف، بل القدرة على المواجهة من أجل من نحب هي رحلة دافئة مليئة بالمغامرة والمعاني الإنسانية، موجهة للأطفال لتعلمهم أن القوة الحقيقية هي التي تسكن القلب.", "/images/products/9786338367787.webp", "9786338367787", "زرو و عشبة الشجاعة", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 525, "غالية يونس محمد", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"قصة ممتعة وهادفة تأخذ الأطفال في رحلة شيّقة مليئة بالمواقف البسيطة والمعاني العميقة، حيث يتعلّمون من خلالها قيَمًا جميلة مثل الصدق، والتعاون، وتحمل المسؤولية. بأسلوب سهل ومحبّب، تساعد القصة الصغار على تنمية خيالهم وتعزيز سلوكياتهم الإيجابية بطريقة ممتعة وشيّقة.\"", "/images/products/9786338367794.webp", "9786338367794", "مروان و كرة الشاطئ", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 527, "جمال بربري", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بين جدرانٍ من طين وسقفٍ من جريد، يرتفعُ صرحٌ من الكرم لا يُغلق بابه ليلاً ولا نهاراً. هي حكايةُ حلمٍ قديم تحول إلى واقعٍ ملموس؛ نخلةٌ شامخة تجودُ بثرائها صيفاً وشتاءً ، وبئرٌ رقراق يرتوي منه الغريبُ قبل القريب.\nيصحبنا الجدُّ في رحلةٍ عبر الزمان ليروي للأحفاد قصة صاحب الدار الذي ذاق مرارة التشرد، فجعل من بيته ملاذاً لكل محتاج ومنارةً لتعليم الأجيال أن يد العطاء هي أصدقُ أثرٍ يتركه الإنسان.\n“بيتُ الخير.. ليس مجرد جدران، بل هو قصةُ إحسانٍ طافت الآفاق لتخبرنا أن العطاء هو نبض الحياة”.", "/images/products/9786338367848.webp", "9786338367848", "بيت الخير", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 528, "أحمد المؤذن", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لما عادت ميسون من مدرستها، عند باب منزلها وجدت مفاجأة في انتظارها، تعرفون ما هي ؟!\nكانت قطـة بيضاء جميلـة تموء بلطـف عند قدميّ ميسون فحملتها في الحال بكل فرح.. لكن والدتها لم ترحب بهذه الزائرة الصغيرة .\nومن منا لا يحب صداقة القـطط الظريفة ؟\nأين ستذهب القطـة المسكينة \" فوفو \"؟", "/images/products/9786338367855.webp", "9786338367855", "ميسون و القطة فوفو", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 529, "احمد المؤذن", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "قصة الدودة لعلكم تعرفونها، تدور أحداثها في المزرعة.\nالحياة في المزرعة تمضي بالتعاون ولكن الدودة المغرورة لها رأي آخر، فهي أنانية ولا تفكرإلا في نفسها ولا تكترث بطبيعة القرارات التي تتخذها.\nحتى نعرف ماذا حصل لها.. تعالوا جميعًا نقرأ الصفحات التالية ونكتشف بقية الأحداث.", "/images/products/9786338367862.webp", "9786338367862", "الدودة المغرورة", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 530, "احمد المؤذن", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "محسن بدأت عـطلته الصيفية، أقترح عليـه والده الذهاب في رحلـة صيد بحريـة. فكر محسن بزرقة البحر الكبير وأشكال القواقـع الغريبة وكيف يسبح السمك في عـمق الماء ولكن هـل سيصطاد تلك السمكة الكبيرة التي زارتـه في حلمــه؟!", "/images/products/9786338367879.webp", "9786338367879", "رحلة صيد", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 531, "احمد المؤذن", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أمل أخبرت صديقتها صفاء ، كيف أنها تعبت كثيراً حتى تمكنت من إقناع شقيقها محمود باستعارة العصفور من أجل شرح حصة العلوم ، كما تعهدت رده إلى البيت وأن لا مشكلة في الأمر.\nصفاء تبحلق في العصفور، له ريش ملون فتان ولكنه صامت كما لو كان حزيناً يضيق بسجنه ، تتأمل صفاء العصفور المسكين بشفقة و تتمنى في سرها لو يكسر باب قفصه و يحلق بعيداً .\nأتعرفون يا أحبائي الصغار ماذا حـدث بعدها؟\nصديقتنا أمـل وقعت في ورطـة!\nأثناء حصة العلوم وقـع القفص من على طـرف طاولة المعلمة و...", "/images/products/9786338367886.webp", "9786338367886", "وطار العصفور", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 532, "احمد المؤذن", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إيمان مندهشة من منظر الغيوم السوداء الداكنة التي تسبح في سماء المدينة ولديها تساؤلات كثيرة، تحدق إلى الأعـلى وهي في حافلة المدرسة قبل أن تقصدها غـيمة صغيرة هبطـت إلى الأرض!\nوما أجمل الدعـوة اللطيفة التي تلقتها الطفلة إيمـان ، مرت لحظات قبل أن تطير بها تلك الغيمـة الظريفة إلى السماء العالية لكن ماذا تفعل إيمان هناك في الأعـلى؟\nثمـة دروس مفيدة ستتعلمها إيـمـان من رحلتها إلى السماء، تعالوا معنا أحبائي الصغار نكتشف مغامرة طـريفة وحلوة هنـاك فوق الغيـوم.\nهيا بسرعـة فالغيمـة الصغيرة لن تبقـى في انتظارها طـويلا ، نزلت إلى الأرض لكونها أحبت صداقـة الطفلة إيمان وبدأت تجيب على أسئلتهـا. كذلك أنتـم يا صغـاري لديكم الكثير من الأسئـلة .", "/images/products/9786338367893.webp", "9786338367893", "فوق الغيوم", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 533, "نهاد مانع", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"قصة ممتعة وهادفة تأخذ الأطفال في رحلة شيّقة مليئة بالمواقف البسيطة والمعاني العميقة، حيث يتعلّمون من خلالها قيَمًا جميلة مثل الصدق، والتعاون، وتحمل المسؤولية. بأسلوب سهل ومحبّب، تساعد القصة الصغار على تنمية خيالهم وتعزيز سلوكياتهم الإيجابية بطريقة ممتعة وشيّقة.\"", "/images/products/9786338367916.webp", "9786338367916", "إبتسامة تعلم", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 534, "غالية يونس محمد", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"قصة ممتعة وهادفة تأخذ الأطفال في رحلة شيّقة مليئة بالمواقف البسيطة والمعاني العميقة، حيث يتعلّمون من خلالها قيَمًا جميلة مثل الصدق، والتعاون، وتحمل المسؤولية. بأسلوب سهل ومحبّب، تساعد القصة الصغار على تنمية خيالهم وتعزيز سلوكياتهم الإيجابية بطريقة ممتعة وشيّقة.\"", "/images/products/9786338367923.webp", "9786338367923", "الجدة تحت البرتقال", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 535, "نهاد مانع", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"قصة ممتعة وهادفة تأخذ الأطفال في رحلة شيّقة مليئة بالمواقف البسيطة والمعاني العميقة، حيث يتعلّمون من خلالها قيَمًا جميلة مثل الصدق، والتعاون، وتحمل المسؤولية. بأسلوب سهل ومحبّب، تساعد القصة الصغار على تنمية خيالهم وتعزيز سلوكياتهم الإيجابية بطريقة ممتعة وشيّقة.\"", "/images/products/9786338367947.webp", "9786338367947", "قصة الحذاء الذى يعرف الطريق", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 543, "منال جميعي", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لقد مللتُ ذلك الاستغلال، لماذا يتوجب علىّ الاستيقاظ مبكرًأ كل يوم بينما الجميع نائمين في فراشهم؟ ثم لماذا عليّ أن أرهق أحبالي الصوتية في النداء بصوتٍ عالٍ حتى يستيقظ الجميع ؟ أنا أريد أن أنام طويلًا كما ينام الجميع واستيقظ في الموعد الذي يحلو لي.", "/images/products/9786338387051.webp", "9786338387051", "الديك المغرور", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 544, "لورين أيمن محمد عبدالمعوض", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "دائما الحياة تعطينا السعادة\nبيدينا نحن أن نسعد أو نوقع أنفسنا في مرهقات الحياة\nنعم افرح واضحك والعب واسعد، ولكن أترك مسافة آمنة لكي لا تصيب من حولك بالضرر أو تصيب نفسك..\nومن هنا أترك لكم قصتي الخارجة من قلب طفلة لتكون بين يد طفل آخر تخلق داخله نصيحة صغيرة", "/images/products/9786338387068.webp", "9786338387068", "فلفول اللعوب", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 551, "إلهام عبدالمعز عبدالتواب", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "قصة إنسانية إجتماعية تخُص فئة مُعينة ، وتصُب الإهتمام نحو شريحة حية في المجتمع .\nنُحلل فيها بعض الطبائع البشرية والسلوكيات المُجتمعية التي تُنافي الدين وتضُر بالمجتمع نفسيًا وتِباعًا لذلك تُعيق نهضة الأمة .\n٠ نُعالجها بالوازع الديني ،الأخلاقي، والنفسي كذا الوازع الفكري لمحاربة السلوم بالأحرى بالوازع الإنساني .\n٠ تمزج بين الواقع والخيال إذا أَطَقْتَ أَدْرِك الواقع من الخيال .", "/images/products/9786338387150.webp", "9786338387150", "مختلفة", null, 100m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 553, "سماح ماضى", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هل السرعة وحدها تصنع البطل؟\nفي فرفور بطل السباق، نعيش مع الأطفال مغامرة ممتعة ومليئة بالضحك، نتعلّم من خلالها أن الفوز ليس أن نصل أولًا، بل أن نعرف الطريق جيدًا.\nقصة ذكية تُظهر أن التفكير، والصبر، والتعاون قد تكون أسرع أثرًا من الجري نفسه، وأن البطل الحقيقي هو من يتعلّم قبل أن يندفع.", "/images/products/9786338387181.webp", "9786338387181", "فرفور بطل السباق", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 577, "شيماء أبو الجمايل حجازى", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدور أحداث قصة «ألم السوسة» حول طفل يحب الحلويات كثيرًا ويهمل تنظيف أسنانه، غير مدركٍ للخطر الصغير الذي يختبئ بينها. ومع مرور الأيام، تبدأ السوسة في إلحاق الأذى بأسنانه، فيشعر بالألم ويتعلم درسًا مهمًا لن ينساه. تأخذنا القصة في رحلة ممتعة ومفيدة، نكتشف من خلالها أهمية النظافة الشخصية، والالتزام بنصائح الوالدين، والعناية بالأسنان للحفاظ على صحتها وجمالها. قصة تربوية مشوقة، بأسلوب بسيط ورسالة هادفة، تساعد الأطفال على فهم العادات الصحيحة بأسلوب ممتع وقريب إلى قلوبهم.", "/images/products/9786338387471.webp", "9786338387471", "ألم السوسة", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 578, "شيماء أبو الجمايل حجازى", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تحكي قصة «الأرنب والسلحفاة» حكاية جميلة عن التعاون والاجتهاد، من خلال سلحفاة نشيطة لا تعرف الكسل، وأرنب يفضل الراحة والنوم على العمل. عندما تواجههما أزمة حقيقية، تثبت السلحفاة أن الجدّ والصبر هما طريق النجاح، وأن من يعمل بجد يحصد ثمرة تعبه. تكشف القصة للأطفال خطورة الكسل، وأهمية التعاون واحترام جهد الآخرين، وأن العمل المشترك هو السبيل لتجاوز الصعوبات. قصة ممتعة تحمل في طياتها درسًا أخلاقيًا مهمًا، تُقدَّم بأسلوب بسيط يساعد الطفل على الفهم ويغرس القيم الإيجابية في نفسه.", "/images/products/9786338387518.webp", "9786338387518", "الأرنب و السلحفاة", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 579, "شيماء أبو الجمايل حجازى", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تحكي قصة «الضفدع لولو الذكي» حكاية ضفدع محبّ للقراءة والمعرفة، يستخدم علمه وذكاءه لحماية أصدقائه من خطرٍ يهدد حياتهم. حين تشتد حرارة الشمس ويقترب الجفاف، يدرك لولو ما سيحدث قبل الآخرين، فيبادر بجمعهم ويقودهم للتعاون والعمل المشترك. تعلّمنا القصة أن العلم نور، وأن التفكير السليم والتخطيط الجيد قادران على إنقاذ الجميع، وأن التعاون والاتحاد يصنعان المعجزات. قصة شيّقة مليئة بالقيم الإيجابية، تُنمّي لدى الطفل حب القراءة، وروح المسؤولية، وأهمية العمل الجماعي في مواجهة الأزمات.", "/images/products/9786338387525.webp", "9786338387525", "الضفدع لولو الذكى", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 587, "نهلة الناقة", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ظن عبدول أن الحقيقة واحدة،\nحتى علمته القطة فلورا أن القلوب ترى بعيون مختلفة.\nكان عبدول واثقًا من رأيه،\nلكن فلورا همست له: ليس كل ما نراه، يراه الآخرون كما نراه!\nفي عالم صغير، تعلم كتكوت عجوز\nأن الاختلاف ليس خصومة… بل حكاية أخرى.\nحكاية تروى للصغار،\nتمنحهم كلمات لمشاعرهم،\nوتزرع في قلوبهم بذور التفهم،\nبينما يجد الكبار فيها بداية حوار دافئ معهم.\nقصة بسيطة في شكلها،\nعميقة في أثرها،\nتبقى معانيها أطول مما تبقى الصفحات!", "/images/products/9786338387662.webp", "9786338387662", "فلورا في حديقة الأفكار", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 598, "أدهم وليد", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "صعدت ريمي المنصة بخطوات ثابتة، شعرها يتلألأ تحت الأضواء، وابتسامتها تخبر الجميع أن الخرافات قد ماتت إلى الأبد.”\nاسم المؤلف: أدهم وليد عبد الرحيم", "/images/products/9786338387891.webp", "9786338387891", "قصة الفتاة ذات الشعر النارى", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 621, "رحاب مشعل", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "قطرة فضولية تريد معرفة المزيد عن رحلتها، كثيرة الأسئلة.. تنتقل مع قطرة خبيرة عبر رحلة مليئة بالمغامرات عبر نهر النيل للتعرف على مصرنا الحبيبة.", "/images/products/9786338419219.webp", "9786338419219", "رحلة قطرة", null, 80m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 630, "أحمد المؤذن", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "والدة الطفـل مازن منزعـجة من تعطـل فرنها القديم عن العمل ولكنها في اليوم التالي حصلت على فرنها الجديد.\nولدها مازن وجد الفرن القديم مـتروكًا في حرارة الشمس، فقام يؤدي بعض حركـات اللعب لكنه دُهـش بمدى استياء فرنهم القديم لما تكلم !\nوهل الأفران تتكلم؟!\nهيا بنا نرافق صديقنا الصغير مـازن كيما نتعرف على تفاصيل الحكاية الشيقـة التي حصلت لـه، أمامه مهمـة حساسة حتى لا ينفـذ الفرن القديم تهديده و...", "/images/products/9786338419318.webp", "9786338419318", "الفرن القديم", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 631, "أحمد المؤذن", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "صغيري أنت تسكـن في المدينة؟ أتعـتـقد بأنها أجمل مكان؛ لا تستعجـل قبل قراءة هذه القصـة لأن الديـك \" صـيّــاح \" حينما قـرر زيـارة صديقـه الديك \" مــســـرور \" في المدينة ، هـل تعرف ماذا حصـل له؟\nهـذه القصـة لك ولهـا، تعـاليا الآن حتى ننـطلق من بدايــة الأحـداث ونكتشف ما الدرس الذي تعلمـه صــيّـاح وقت مـغادرته للـريف ومـزرعـته الخضراء الوادعــة، هـيا بسـرعـة فهنا أحـداث كـثيرة ومشوقـة تنتظـرنــا!", "/images/products/9786338419325.webp", "9786338419325", "المدينة أجمل من الريف ؟", null, 50m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false }
                });
